INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (5, 'M05.16', 'Exam Question Bank', 16)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The binary equivalent of 5 is:', '[{"id": "a", "text": "100", "correct": false}, {"id": "b", "text": "110", "correct": false}, {"id": "c", "text": "101", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The program counter of a microprocessor contains:', '[{"id": "a", "text": "a datum", "correct": false}, {"id": "b", "text": "an address", "correct": true}, {"id": "c", "text": "an instruction", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fibre optics work on the principle of:', '[{"id": "a", "text": "total internal refraction", "correct": false}, {"id": "b", "text": "signal reshaping", "correct": false}, {"id": "c", "text": "total internal reflection", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The ARINC 429 standard word consists of:', '[{"id": "a", "text": "8 bits", "correct": false}, {"id": "b", "text": "32 bits", "correct": true}, {"id": "c", "text": "64 bits", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An electronic device that has digital input and analogue output is called:', '[{"id": "a", "text": "a digital to analogue converter", "correct": true}, {"id": "b", "text": "an electronic inverter", "correct": false}, {"id": "c", "text": "demodulator", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How many possible combinations are represented by three binary digits?', '[{"id": "a", "text": "4", "correct": false}, {"id": "b", "text": "8", "correct": true}, {"id": "c", "text": "64", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following would give a navigational information to the flight crew?', '[{"id": "a", "text": "EFIS", "correct": true}, {"id": "b", "text": "ECAM", "correct": false}, {"id": "c", "text": "Both EFIS and ECAM", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The ARINC 429 is:', '[{"id": "a", "text": "a one way bus", "correct": true}, {"id": "b", "text": "a one way bus with parallel data transmission", "correct": false}, {"id": "c", "text": "a two way bus", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How many bits are in 2 KiB (two binary kilobytes)?', '[{"id": "a", "text": "2000", "correct": false}, {"id": "b", "text": "16384", "correct": true}, {"id": "c", "text": "2048", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following devices are most susceptible to electrostatic damage (ESDS) ?', '[{"id": "a", "text": "bipolar transistor", "correct": false}, {"id": "b", "text": "silicon controlled rectifiers", "correct": false}, {"id": "c", "text": "field effect transistor", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On a modern glass cockpit aircraft, engine parameters may be displayed on the:', '[{"id": "a", "text": "electronic centralised aircraft monitoring system", "correct": true}, {"id": "b", "text": "electronic flight instrument system", "correct": false}, {"id": "c", "text": "flight management system", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a functional and operating circuit, the logic gate''s output will be 0:', '[{"id": "a", "text": "only when all inputs are 0", "correct": false}, {"id": "b", "text": "when all inputs are 1", "correct": false}, {"id": "c", "text": "when one or more inputs are 0", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An AND gate with three inputs can be used in a landing gear indicator system to give the same information as:', '[{"id": "a", "text": "3 switches in parallel", "correct": false}, {"id": "b", "text": "3 switches in series", "correct": true}, {"id": "c", "text": "unlimited number of switches in parallel", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'One of the major advantages of a fly by wire aircraft is that the aircraft:', '[{"id": "a", "text": "is easier to fly", "correct": false}, {"id": "b", "text": "it''s flight envelope is protected", "correct": true}, {"id": "c", "text": "will automatically correct it''s position if a resolution advisory is given from TCAS", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the name of the following symbol?', '[{"id": "a", "text": "NOR", "correct": true}, {"id": "b", "text": "AND", "correct": false}, {"id": "c", "text": "OR", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How many possible input combinations exist for five binary inputs?', '[{"id": "a", "text": "64", "correct": false}, {"id": "b", "text": "1024", "correct": false}, {"id": "c", "text": "32", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'To ''''brighten" a plan position indicator tube display, the tubes cathode must be made more:', '[{"id": "a", "text": "negative or the grid more positive", "correct": true}, {"id": "b", "text": "negative or the grid more negative", "correct": false}, {"id": "c", "text": "positive or the grid more negative", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The master caution light is a:', '[{"id": "a", "text": "steady red light", "correct": false}, {"id": "b", "text": "steady amber light", "correct": true}, {"id": "c", "text": "flashing red light", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The signed byte 00010110 is a:', '[{"id": "a", "text": "negative number", "correct": false}, {"id": "b", "text": "positive even number", "correct": true}, {"id": "c", "text": "positive add number", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the purpose of the parity bit in an ARINC 429 word?', '[{"id": "a", "text": "Make the total number of 1 bits in the complete word odd.", "correct": true}, {"id": "b", "text": "Make the total number of 1 bits even. [Reconstructed distractor.]", "correct": false}, {"id": "c", "text": "Correct every corrupted data bit automatically. [Reconstructed distractor.]", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A byte-addressed 2 KiB RAM whose first address is zero is:', '[{"id": "a", "text": "read only memory with memory size 2024 bytes", "correct": false}, {"id": "b", "text": "read/write and may be addressed in hexadecimal code from 0000 to 07ff", "correct": true}, {"id": "c", "text": "read/write memory with memory size 2000 bytes", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC 429 bus is constructed of:', '[{"id": "a", "text": "One shielded twisted pair, carrying a unidirectional differential signal.", "correct": true}, {"id": "b", "text": "Two twisted and shielded pairs that are both bidirectional.", "correct": false}, {"id": "c", "text": "One shielded twisted pair carrying a bidirectional channel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the radix (base) of hexadecimal?', '[{"id": "a", "text": "Base 16.", "correct": true}, {"id": "b", "text": "Base 8.", "correct": false}, {"id": "c", "text": "Base 4.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Access time to STATIC RAM is:', '[{"id": "a", "text": "equal to that of dynamic RAM", "correct": false}, {"id": "b", "text": "faster than dynamic RAM", "correct": true}, {"id": "c", "text": "slower than dynamic RAM", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following are advantages of fibre optics?', '[{"id": "a", "text": "easy to report, cheap, no wear out, imperious to contamination", "correct": false}, {"id": "b", "text": "no movable parts, mechanically robust", "correct": false}, {"id": "c", "text": "reduced weight, higher speed, reduced electromagnetic interference", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A colour cathode ray tube contains three electrical guns they produce the three band colours:', '[{"id": "a", "text": "cyan, magenta and yellow", "correct": false}, {"id": "b", "text": "red, blue and green", "correct": true}, {"id": "c", "text": "black, white and green", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A conventional binary encoder usually has:', '[{"id": "a", "text": "less number of inputs compared to the number of outputs", "correct": false}, {"id": "b", "text": "less number of outputs compared to the number of inputs", "correct": true}, {"id": "c", "text": "an equal number of inputs and outputs", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For a basic active-high NOR SR latch, which asserted input combination is forbidden?', '[{"id": "a", "text": "S = 1, R = 0.", "correct": false}, {"id": "b", "text": "S = R = 1.", "correct": true}, {"id": "c", "text": "S = R = 0.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For a logic 1, what is the nominal ARINC 429 transmitter differential voltage Data A minus Data B?', '[{"id": "a", "text": "+ 5 volts", "correct": false}, {"id": "b", "text": "+ 10 volts", "correct": true}, {"id": "c", "text": "- 10 volts", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The EFIS symbol generator function is:', '[{"id": "a", "text": "to allow the maintenance staff to proceed a bite test", "correct": false}, {"id": "b", "text": "to receive compute data from sensors and send them towards appropriate screens", "correct": true}, {"id": "c", "text": "to generate ARINC words in BCD", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How many bits are in the basic ARINC 429 data field, positions 11 through 29?', '[{"id": "a", "text": "32.", "correct": false}, {"id": "b", "text": "19.", "correct": true}, {"id": "c", "text": "8.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following actions should be carried out after removing an electrostatic discharge sensitive (ESDS) line replaceable unit (LRU) from an equipment rack?', '[{"id": "a", "text": "fit ESDS connector cap", "correct": true}, {"id": "b", "text": "fit ESDS label", "correct": false}, {"id": "c", "text": "store it away from all other equipment", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The clear key of the flight management system is used to remove:', '[{"id": "a", "text": "only incorrect entries from the data computer performance system", "correct": false}, {"id": "b", "text": "any entries from the scratch pad", "correct": true}, {"id": "c", "text": "any of the data displayed", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For an active non-latched EICAS alert, when its triggering condition no longer exists, how is the message normally removed?', '[{"id": "a", "text": "by pressing a cancel switch on the display unit", "correct": false}, {"id": "b", "text": "automatically", "correct": true}, {"id": "c", "text": "by pressing a cancel switch on the display select panel", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the minimum satellite count for an ordinary GPS receiver to solve unconstrained 3D position and receiver clock bias?', '[{"id": "a", "text": "5", "correct": false}, {"id": "b", "text": "3", "correct": false}, {"id": "c", "text": "4", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Areas on the aircraft that are most susceptible to HIRF penetration are:', '[{"id": "a", "text": "flight control surfaces", "correct": false}, {"id": "b", "text": "cockpit and passenger windows", "correct": true}, {"id": "c", "text": "fuselage", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A disadvantage of the analogue to digital converter shown below is that:', '[{"id": "a", "text": "Requires 2ⁿ-1 comparators for an n-bit flash conversion.", "correct": true}, {"id": "b", "text": "Always requires a Gray-code encoder.", "correct": false}, {"id": "c", "text": "Has fast conversion dominated by comparator/encoder propagation delay.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A ROM can be used as a BCD to seven segment decoder. The ROM requires:', '[{"id": "a", "text": "7 inputs", "correct": false}, {"id": "b", "text": "4 inputs", "correct": true}, {"id": "c", "text": "6 inputs", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which numbering code is used for the word “Label” identification?', '[{"id": "a", "text": "octal binary", "correct": true}, {"id": "b", "text": "hexadecimal binary", "correct": false}, {"id": "c", "text": "BCD binary", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In the traditional raster-versus-stroke CRT comparison, which listed image is particularly suited to raster scanning?', '[{"id": "a", "text": "to display weather radar information on the screen", "correct": true}, {"id": "b", "text": "to display numerical information at the beginning of each line (when not blanked out)", "correct": false}, {"id": "c", "text": "to display NAV-AIDS on the screen", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), '375 hexadecimal, when converted into a value of the binary system is:', '[{"id": "a", "text": "001101110101", "correct": true}, {"id": "b", "text": "001111101010", "correct": false}, {"id": "c", "text": "110010101110", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), '(Refer to figure).If input A is 0 and B is 1,output C is:', '[{"id": "a", "text": "Logic “0”", "correct": false}, {"id": "b", "text": "+10 V", "correct": false}, {"id": "c", "text": "Logic “1”", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The program counter in a microprocessor is used to store:', '[{"id": "a", "text": "the address of the next instruction to be executed", "correct": true}, {"id": "b", "text": "the result of a calculation", "correct": false}, {"id": "c", "text": "one of the operands", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On a modern passenger aircraft the Electronic Attitude Director Indicator is normally a combination of aircraft pitch and roll attitude.-', '[{"id": "a", "text": "flight director command bars, slip indication, range to altitude and autoland indications", "correct": false}, {"id": "b", "text": "glideslope daviation, magnetic compass rose, flight director command bars and slip indication", "correct": false}, {"id": "c", "text": "slip indication, radio altitude, decision height and autoland indications", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which listed group consists of actual avionics data-bus standards?', '[{"id": "a", "text": "ARINC 429, MIL-STD 1553 AND ARINC 604", "correct": false}, {"id": "b", "text": "ARINC 600, bi directional ARINC 629,ARINC 453", "correct": false}, {"id": "c", "text": "ARINC 429, (high and low speed) ARINC 659, ARINC 629 bi directional", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which method can select supported LRU software options without replacing boards or reprogramming the installed image?', '[{"id": "a", "text": "select different connector option pins", "correct": true}, {"id": "b", "text": "remove and replace various painted circuit boards mounted ICS", "correct": false}, {"id": "c", "text": "requires reprogramming of the software", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Add the binary numbers 10011111 and 01011001:', '[{"id": "a", "text": "11011100", "correct": false}, {"id": "b", "text": "01110001", "correct": false}, {"id": "c", "text": "11111000", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For the conventional full seven-segment glyph 9 (including its lower bar), which segments light for BCD 1001?', '[{"id": "a", "text": "A, B, C, D, E, F.", "correct": false}, {"id": "b", "text": "B and C only.", "correct": false}, {"id": "c", "text": "A, B, C, D, F, G.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), '(Refer to figure).Figure shows one electrical implementation of a logical:', '[{"id": "a", "text": "OR gate", "correct": true}, {"id": "b", "text": "INVERTER gate", "correct": false}, {"id": "c", "text": "AND gate", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The logic table illustrated is that of an:', '[{"id": "a", "text": "XOR gate whose symbol is scheme 3", "correct": false}, {"id": "b", "text": "XNOR gate whose symbol is scheme1", "correct": true}, {"id": "c", "text": "NOR gate whose symbol is scheme 2", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a traditional CRT display architecture requiring analogue drive signals, what converts digital display data into those signals?', '[{"id": "a", "text": "adjusting the mode control", "correct": false}, {"id": "b", "text": "a digital to analogue converter", "correct": true}, {"id": "c", "text": "a stabilized voltage input", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a classical accumulator-based microprocessor, which register normally holds the result of an arithmetic operation?', '[{"id": "a", "text": "the arithmetic logic unit (ALU)", "correct": false}, {"id": "b", "text": "the accumulator", "correct": true}, {"id": "c", "text": "the data register", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Conversion of binary number 100101101 to decimal is:', '[{"id": "a", "text": "301", "correct": true}, {"id": "b", "text": "310", "correct": false}, {"id": "c", "text": "331", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a four input multiplexer, the input selection needs:', '[{"id": "a", "text": "4 bits", "correct": false}, {"id": "b", "text": "2 bits", "correct": true}, {"id": "c", "text": "1 bit only", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For a suitably designed long/high-bandwidth link, which listed potential channel benefit can optical fibre offer relative to the compared copper link?', '[{"id": "a", "text": "less maintenance is required", "correct": false}, {"id": "b", "text": "it uses less power", "correct": false}, {"id": "c", "text": "there is lower attenuation", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Registers are used in digital computers to:', '[{"id": "a", "text": "store bits of information in a permanent memory", "correct": false}, {"id": "b", "text": "keep a count of operations completed", "correct": false}, {"id": "c", "text": "store a limited amount of information on a temporary basis", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a microprocessor system the control bus is:', '[{"id": "a", "text": "a bi-directional bus", "correct": true}, {"id": "b", "text": "a unidirectional bus", "correct": false}, {"id": "c", "text": "a high speed bus", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The type of diode used in a fibre optic transmitter is usually:', '[{"id": "a", "text": "injection laser diode", "correct": true}, {"id": "b", "text": "silicon light emitting diode", "correct": false}, {"id": "c", "text": "germanium photo diode", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following truth tables describes an EXOR gate?', '[{"id": "a", "text": "truth table 2", "correct": false}, {"id": "b", "text": "truth table 1", "correct": false}, {"id": "c", "text": "truth table 3", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Light is confined within the core of a simple optical fibre by:', '[{"id": "a", "text": "reflection from the fibre’s plastic coating", "correct": false}, {"id": "b", "text": "total internal reflection at the outer edge of the cladding", "correct": false}, {"id": "c", "text": "total internal reflection at the core cladding boundary", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Convert binary 101101011100 to hexadecimal.', '[{"id": "a", "text": "DLH.", "correct": false}, {"id": "b", "text": "DA3.", "correct": false}, {"id": "c", "text": "B5C.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The output level of the circuit below is Q=1 when the input combination is:', '[{"id": "a", "text": "I0 = 0, I1 = 1, I2 = 0.", "correct": false}, {"id": "b", "text": "I0 = 1, I1 = 0, I2 = 0.", "correct": false}, {"id": "c", "text": "I0 = 1, I1 = 1, I2 = 0.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'B hexadecimal when converted into a value of the binary system is:', '[{"id": "a", "text": "1011", "correct": true}, {"id": "b", "text": "1100", "correct": false}, {"id": "c", "text": "0110", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Using laser diodes instead of light emitting diodes (LED) in fibre optic transmission systems has the advantage of:', '[{"id": "a", "text": "being cheaper", "correct": false}, {"id": "b", "text": "lower attenuation", "correct": false}, {"id": "c", "text": "higher transmission rates", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following electronic roles could a demultiplexer perform?', '[{"id": "a", "text": "parallel in/parallel out data transfer", "correct": false}, {"id": "b", "text": "serial in/serial out data transfer", "correct": false}, {"id": "c", "text": "serial in/parallel out data transfer", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The circuit illustrated is a:', '[{"id": "a", "text": "JK flip flops working like a shift register", "correct": false}, {"id": "b", "text": "serial/parallel converter", "correct": false}, {"id": "c", "text": "counter (4 bits)", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In the circuit illustrated V out is:', '[{"id": "a", "text": "0", "correct": true}, {"id": "b", "text": "1", "correct": false}, {"id": "c", "text": "V out is not determined as this is a sequential logic circuit", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Typical displays on an EHSI are', '[{"id": "a", "text": "Engine indications.", "correct": false}, {"id": "b", "text": "VOR, Map, Plan and weather radar.", "correct": true}, {"id": "c", "text": "VOR, Plan, Map and Attitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An EADI display showing a moving runway moves down during the final stages of an approach. The aircraft must', '[{"id": "a", "text": "fly down.", "correct": true}, {"id": "b", "text": "fly up.", "correct": false}, {"id": "c", "text": "hold descent path.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'During an instrument approach, the glideslope pointer eflects below the glideslope centre mark. This means the aircraft is positioned', '[{"id": "a", "text": "above the glideslope.", "correct": true}, {"id": "b", "text": "below the glideslope.", "correct": false}, {"id": "c", "text": "to the left of the localiser.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Engine parameters are displayed on', '[{"id": "a", "text": "ECAM.", "correct": true}, {"id": "b", "text": "EHSI.", "correct": false}, {"id": "c", "text": "FMSCDU.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the fixed feature of an ADI?', '[{"id": "a", "text": "The glideslope pointer.", "correct": false}, {"id": "b", "text": "The aircraft symbol.", "correct": true}, {"id": "c", "text": "The lateral deviation bar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On an EADI, the Flight Director command bars show', '[{"id": "a", "text": "the path with respect to the horizon.", "correct": false}, {"id": "b", "text": "the required path with respect to the actual path.", "correct": true}, {"id": "c", "text": "the actual path with respect to the required path.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What instrument includes a display of a rising runway?', '[{"id": "a", "text": "ECAM.", "correct": false}, {"id": "b", "text": "EHSI.", "correct": false}, {"id": "c", "text": "EADI.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What functions are available on the EHSI?', '[{"id": "a", "text": "Full arc and Wx only.", "correct": false}, {"id": "b", "text": "Full arc, Wx and Map Mode.", "correct": true}, {"id": "c", "text": "Full Arc only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'With radio coupled autopilot, what are the inputs?', '[{"id": "a", "text": "ADF and VOR.", "correct": false}, {"id": "b", "text": "ILS and VOR.", "correct": true}, {"id": "c", "text": "ADF and ILS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An EADI display of flight director commands are coloured', '[{"id": "a", "text": "cyan.", "correct": false}, {"id": "b", "text": "magenta.", "correct": true}, {"id": "c", "text": "red.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'EFIS systems have two control panels, their purpose is:', '[{"id": "a", "text": "one to control the type of EFIS display and the other to select the source of the information being displayed.", "correct": true}, {"id": "b", "text": "one for the EADI display and one for the EHSI display.", "correct": false}, {"id": "c", "text": "to provide display control by one control panel whilst the other provides a standby.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What would you expect to see displayed on an EADI display?', '[{"id": "a", "text": "Compass heading, selected heading and VOR.", "correct": false}, {"id": "b", "text": "Course information, weather radar, way point alert and bearing pointers.", "correct": false}, {"id": "c", "text": "Flight director command bars, slip indicator, rate to altitude & autoland.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An EFIS ADI display will show along with pitch and roll', '[{"id": "a", "text": "flight director bars, autoland, compass rose, altitude.", "correct": false}, {"id": "b", "text": "decision height, autoland, rad alt , altitude.", "correct": false}, {"id": "c", "text": "flight director bars, autoland, altitude, range to altitude, decision height. ← corrected answer", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If the glideslope pointer is below the centre mark the aircraft is', '[{"id": "a", "text": "below the glideslope.", "correct": false}, {"id": "b", "text": "on the glideslope.", "correct": false}, {"id": "c", "text": "above the glideslope.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On an EFIS system the weather radar is displayed on', '[{"id": "a", "text": "the FMC CDU.", "correct": false}, {"id": "b", "text": "the EADI.", "correct": false}, {"id": "c", "text": "the EHSI.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'EADI displays show', '[{"id": "a", "text": "pitch, roll and waypoints.", "correct": false}, {"id": "b", "text": "pitch and roll attitudes.", "correct": true}, {"id": "c", "text": "heading and weather radar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On an EHSI in weather radar mode, a severe storm would be shown as', '[{"id": "a", "text": "orange areas with black or yellow surrounds.", "correct": false}, {"id": "b", "text": "red areas with black surrounds.", "correct": true}, {"id": "c", "text": "blue areas with white background.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'During flight (non fault conditions) the EICAS system displays on the lower CRT', '[{"id": "a", "text": "flight phase page.", "correct": false}, {"id": "b", "text": "secondary engine parameters.", "correct": true}, {"id": "c", "text": "synoptic display.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Radio altitude is displayed on an EFIS system', '[{"id": "a", "text": "on the Electronic Horizontal Situation Indicator.", "correct": false}, {"id": "b", "text": "on the Electronic Attitude Direction Indicator.", "correct": true}, {"id": "c", "text": "on the RMI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An EFIS system ADI displays pitch, roll', '[{"id": "a", "text": "autoland, altitude, compass rose and flight director bars.", "correct": false}, {"id": "b", "text": "autoland, decision height, range to altitude and flight director bars and slip indicator.", "correct": true}, {"id": "c", "text": "autoland, rad alt, decision height and slip indicator.", "correct": false}]'::jsonb, '{B1,B2}'),
