    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The EFIS system consists of', '[{"id": "a", "text": "EHSI, Mode control panel, EADI.", "correct": false}, {"id": "b", "text": "EADI, EHSI, Symbol generators.", "correct": true}, {"id": "c", "text": "Mode control Panel, RDMI, EHSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ILS indications on PFD/ND are shown in', '[{"id": "a", "text": "cyan.", "correct": false}, {"id": "b", "text": "magenta.", "correct": true}, {"id": "c", "text": "green.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A weather radar image can be displayed on the ND on all modes except', '[{"id": "a", "text": "arc.", "correct": false}, {"id": "b", "text": "nav rose.", "correct": false}, {"id": "c", "text": "plan.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A modern Electronic Horizontal Situation Indicator will display the following:', '[{"id": "a", "text": "Waypoints, ILS Steering Information, Distance to go and Magnetic Heading.", "correct": true}, {"id": "b", "text": "ILS Steering Information, Flight director information and Glide Slope Deviation.", "correct": false}, {"id": "c", "text": "Ground speed, Magnetic Heading, Way points and Localiser.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A complete EFIS installation in an aircraft is made up of', '[{"id": "a", "text": "either of the above. ← was marked in the original", "correct": false}, {"id": "b", "text": "right (captain) and left (co-pilot).", "correct": false}, {"id": "c", "text": "left (captain) and right (co-pilot). ← corrected answer", "correct": true}]'::jsonb, '{B1,B2}'),
