    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Within a computer controlled flight system, position feedback is converted from', '[{"id": "a", "text": "position feedback to rate feedback.", "correct": false}, {"id": "b", "text": "analogue to digital.", "correct": true}, {"id": "c", "text": "digital to analogue.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is serial to parallel and vice-versa called?', '[{"id": "a", "text": "Switching.", "correct": false}, {"id": "b", "text": "Multiplex/Demultiplex.", "correct": true}, {"id": "c", "text": "Encoder/Decoder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A thyristor is a device which has', '[{"id": "a", "text": "a positive temperature coefficient.", "correct": false}, {"id": "b", "text": "a negative temperature coefficient.", "correct": true}, {"id": "c", "text": "a temperature coefficient of zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Physical variables in quantitative forms, such as voltage or angular rotation of a shaft are', '[{"id": "a", "text": "digital.", "correct": false}, {"id": "b", "text": "analogue.", "correct": true}, {"id": "c", "text": "binary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A D to A converter is required to produce an output range of 0 to 10V. This can be achieved by', '[{"id": "a", "text": "a non inverting op amp connected in series with output.", "correct": true}, {"id": "b", "text": "an inverting op amp connected in series with output.", "correct": false}, {"id": "c", "text": "a differentiator with a 100 Kilohm feedback resistor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A D to A converter would use a precision amplifier to', '[{"id": "a", "text": "compensate for the variation of the feedback resistor with temperature.", "correct": false}, {"id": "b", "text": "ensure that the output voltages remain accurate.", "correct": true}, {"id": "c", "text": "ensure that the input voltage remains accurate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An A to D converter uses successive approximation to', '[{"id": "a", "text": "increase resolution.", "correct": false}, {"id": "b", "text": "increase accuracy.", "correct": false}, {"id": "c", "text": "increase speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An R-2R D to A converter uses', '[{"id": "a", "text": "two values of resistors whose precision is not important..", "correct": false}, {"id": "b", "text": "two values of precision resistors. ← corrected answer", "correct": true}, {"id": "c", "text": "resistors whose values are logarithmic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The function of a commutator is to', '[{"id": "a", "text": "convert from analogue to binary form.", "correct": false}, {"id": "b", "text": "provide continuous availability of all parameters connected to the system.", "correct": false}, {"id": "c", "text": "provide a sampling in sequence of a number of parameters.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An encoder using Grey code', '[{"id": "a", "text": "changes analogue to binary.", "correct": false}, {"id": "b", "text": "changes digital to analogue.", "correct": false}, {"id": "c", "text": "changes analogue to digital.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An analogue to digital converter is as accurate as', '[{"id": "a", "text": "the frequency.", "correct": false}, {"id": "b", "text": "the sampling rate.", "correct": true}, {"id": "c", "text": "the amplitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A digital to analogue converter that requires the output to range between 0v and -10v would have', '[{"id": "a", "text": "a non-inverting amplifier in line with the output with a resistor to ground.", "correct": false}, {"id": "b", "text": "an inverting amplifier in series with the output line.", "correct": true}, {"id": "c", "text": "a non-inverting amplifier in parallel with the output line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In an analogue to digital converter, the input voltage', '[{"id": "a", "text": "is switched by the digital input.", "correct": false}, {"id": "b", "text": "is intermittent.", "correct": false}, {"id": "c", "text": "stays on constantly.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An R-2R Converter has values or resistance', '[{"id": "a", "text": "whose relative precision are accurate. ← corrected answer", "correct": true}, {"id": "b", "text": "whose precision are not accurate.", "correct": false}, {"id": "c", "text": "whose precision are accurate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What does 1 represent in an analogue system?', '[{"id": "a", "text": "High frequency", "correct": false}, {"id": "b", "text": "Switches closed, magnetised", "correct": true}, {"id": "c", "text": "Switches open, unmagnetised", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Audio sounds recorded digitally', '[{"id": "a", "text": "are superior quality and graeter bandwidth.", "correct": true}, {"id": "b", "text": "are narrow bandwidth.", "correct": false}, {"id": "c", "text": "are not as accurate due to clipping and input errors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An analogue to digital converter where it counts up to binary state equal to the analogue input and then back down when this is reached is', '[{"id": "a", "text": "a ramp type converter.", "correct": true}, {"id": "b", "text": "a successive approximation counter.", "correct": false}, {"id": "c", "text": "a flash type converter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Transistors are used in a current triggered D to A device to', '[{"id": "a", "text": "switch off the inputs.", "correct": false}, {"id": "b", "text": "switch on the input.", "correct": false}, {"id": "c", "text": "change the state of the inputs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Op amps generally used in ADCs and DACs are normally', '[{"id": "a", "text": "high input impedance, high output impedance.", "correct": false}, {"id": "b", "text": "high input impedance, low output impedance.", "correct": true}, {"id": "c", "text": "low input impedance , how output impedance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Analogue logic 1 is', '[{"id": "a", "text": "closed switch, Logic Q=0.", "correct": false}, {"id": "b", "text": "closed circuit, Logic Q=1.", "correct": true}, {"id": "c", "text": "open circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ADC uses successive approximation to', '[{"id": "a", "text": "increase speed.", "correct": true}, {"id": "b", "text": "increase accuracy.", "correct": false}, {"id": "c", "text": "increase resolution.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A DAC uses a precision amplifier to', '[{"id": "a", "text": "ensure the output voltages remain accurate.", "correct": true}, {"id": "b", "text": "compensates for the variation of the feedback resistor due to temperature.", "correct": false}, {"id": "c", "text": "ensure the input remains accurate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A precision op-amp is used in a DAC to', '[{"id": "a", "text": "compensate for temperature variation.", "correct": false}, {"id": "b", "text": "give output at required level.", "correct": true}, {"id": "c", "text": "make output between 0 - 5V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In an R-2R ladder converter the values of resistors', '[{"id": "a", "text": "do not need to be of precise values.", "correct": false}, {"id": "b", "text": "only the first resistor need to be precise.", "correct": false}, {"id": "c", "text": "are precise", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the quickest method of analogue to digital conversion?', '[{"id": "a", "text": "Voltage to frequency.", "correct": false}, {"id": "b", "text": "Flash converter.", "correct": true}, {"id": "c", "text": "Single ramp method.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A charge balancing ADC uses', '[{"id": "a", "text": "successive approximation logic circuit to control the output.", "correct": false}, {"id": "b", "text": "a closed loop system to compare the analogue input to give the required digital output.", "correct": true}, {"id": "c", "text": "a closed loop system to check the analogue input with the input sample.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Sample and hold is a technique used in', '[{"id": "a", "text": "D to A conversion.", "correct": false}, {"id": "b", "text": "Moving coil instruments.", "correct": false}, {"id": "c", "text": "A to D conversion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An analogue to digital converter (ADC) requires the following:', '[{"id": "a", "text": "a reference voltage, an input gate, a comparato", "correct": false}, {"id": "b", "text": "a reference voltage, an input gate, an internal counter, a comparator.", "correct": true}, {"id": "c", "text": "a reference voltage, an input gate, an internal counter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the Resolution of A/D and D/A converters?', '[{"id": "a", "text": "Resolution of the Instrument which displays the values.", "correct": false}, {"id": "b", "text": "Number of discrete values that can be represented by the digital word.", "correct": true}, {"id": "c", "text": "Rate at which data is converted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Digital signals can be represented', '[{"id": "a", "text": "only as a binary value.", "correct": false}, {"id": "b", "text": "by a series of integers.", "correct": true}, {"id": "c", "text": "by real numbers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When testing EGT probe', '[{"id": "a", "text": "it must be soaked and ambient temperature allowance taken into consideration.", "correct": true}, {"id": "b", "text": "not necessarily soaked but ambient temperature must be taken into consideration.", "correct": false}, {"id": "c", "text": "if its not soaked, a minimum temperature of 20 degrees C taken as OAT.", "correct": false}]'::jsonb, '{B1,B2}'),
