    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In aircraft use, fibre optic cables should comply with', '[{"id": "a", "text": "ARINC 629 standard.", "correct": false}, {"id": "b", "text": "ARIND 429 standard.", "correct": false}, {"id": "c", "text": "ARIND 636 standard.", "correct": true}]'::jsonb, '{B1,B2}'),
