    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How many LRUs can be connected to an ARINC 429 data bus?', '[{"id": "a", "text": "120.", "correct": false}, {"id": "b", "text": "60.", "correct": false}, {"id": "c", "text": "20.", "correct": true}]'::jsonb, '{B1,B2}'),
