    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC 429 bus uses', '[{"id": "a", "text": "a twisted shielded pair of wires.", "correct": true}, {"id": "b", "text": "a single twin cable for each transmitter.", "correct": false}, {"id": "c", "text": "two bi-directional twin, sheathed and earthed wires.", "correct": false}]'::jsonb, '{B1,B2}'),
