    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC 429 system uses a', '[{"id": "a", "text": "20 bit word over a bi-directional bus.", "correct": false}, {"id": "b", "text": "32 bit word over a twisted pair of wires.", "correct": true}, {"id": "c", "text": "16 bit word over a twisted pair of wires.", "correct": false}]'::jsonb, '{B1,B2}'),
