    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Data is transferred on the MIL-STD-1553B by', '[{"id": "a", "text": "non return to zero.", "correct": false}, {"id": "b", "text": "Manchester bi-phase.", "correct": true}, {"id": "c", "text": "bi-polar return to zero.", "correct": false}]'::jsonb, '{B1,B2}'),
