    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On an ARINC 629 data bus, the maximum amount of current-mode couplers per data bus is', '[{"id": "a", "text": "46.", "correct": false}, {"id": "b", "text": "120.", "correct": true}, {"id": "c", "text": "64.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'To connect an LRU to the data bus', '[{"id": "a", "text": "a terminal controller and interface module only is required.", "correct": false}, {"id": "b", "text": "current mode coupler, terminal controller and a production break is required.", "correct": false}, {"id": "c", "text": "a current mode coupler, serial interface module and terminal controller is required.", "correct": true}]'::jsonb, '{B1,B2}'),
