    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC 629 bus cable is a twisted pair of wires with', '[{"id": "a", "text": "a 130 ohm resistor at one end.", "correct": false}, {"id": "b", "text": "a 130 ohm resistor at both ends.", "correct": true}, {"id": "c", "text": "a 230 ohm resistor at one end.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC 629 stub cable', '[{"id": "a", "text": "connects single directional data between the LRU and current mode coupler.", "correct": false}, {"id": "b", "text": "connects bi-directional data between the LRU and current mode coupler.", "correct": true}, {"id": "c", "text": "connects bi-directional data between two LRUs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Care must be taken when installing ARINC 629 cables into bus panels, damage to cables can cause', '[{"id": "a", "text": "corrosion of the conductor", "correct": false}, {"id": "b", "text": "arcing of high voltage signals.", "correct": false}, {"id": "c", "text": "standing waves. ← corrected answer", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An aircraft databus system', '[{"id": "a", "text": "can use both ARINC 629 and ARINC 429 as they are compatible.", "correct": false}, {"id": "b", "text": "can use both systems, ARINC 629 and ARINC 429 via system card files and signal gateways.", "correct": true}, {"id": "c", "text": "cannot use both ARINC 629 and ARINC 429 data buses.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ARINC 629 is used for', '[{"id": "a", "text": "emergency only.", "correct": false}, {"id": "b", "text": "a backup to ARINC 429.", "correct": false}, {"id": "c", "text": "normal flight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Once an ARINC 629 LRU has transmitted a message it will wait how long before transmitting again?', '[{"id": "a", "text": "Until the end of the synchronization gap.", "correct": false}, {"id": "b", "text": "Until the start of the terminal gap.", "correct": false}, {"id": "c", "text": "Until the end of the transmit interval.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How is the word label 206 written in ARINC 429?', '[{"id": "a", "text": "Decimal 206.", "correct": false}, {"id": "b", "text": "Octal 01100001.", "correct": true}, {"id": "c", "text": "Binary 11000110.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is ARINC 561 used for?', '[{"id": "a", "text": "Fly by Wire systems.", "correct": false}, {"id": "b", "text": "Flight Data Recorder systems.", "correct": false}, {"id": "c", "text": "Inertial Navigation Systems.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC data word is bits 11-29, if bits 11-18 are patched which of the following would be the LSB bit?', '[{"id": "a", "text": "19.", "correct": true}, {"id": "b", "text": "29.", "correct": false}, {"id": "c", "text": "21.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fibreoptic databus links are', '[{"id": "a", "text": "simplex.", "correct": false}, {"id": "b", "text": "bi-directional.", "correct": true}, {"id": "c", "text": "one way data buses.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ARINC 629 is', '[{"id": "a", "text": "half duplex.", "correct": true}, {"id": "b", "text": "full duplex.", "correct": false}, {"id": "c", "text": "simplex.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A signal in an ARINC 629 system uses', '[{"id": "a", "text": "a pair of wires per transmitter unit.", "correct": false}, {"id": "b", "text": "a single wire.", "correct": false}, {"id": "c", "text": "a twisted pair of wires or fibre optics.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An in-series ARINC 429 system transmits using', '[{"id": "a", "text": "encoder.", "correct": false}, {"id": "b", "text": "time division multiplexing.", "correct": true}, {"id": "c", "text": "wave division multiplexing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A terminal controller', '[{"id": "a", "text": "is repetitive transmitting.", "correct": false}, {"id": "b", "text": "will transmit only once during each transmit interval.", "correct": true}, {"id": "c", "text": "transmits only when addressed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The number of LRUs which transmit/receive on ARINC-429 is dependent upon', '[{"id": "a", "text": "speed of transmission & size of aircraft systems.", "correct": false}, {"id": "b", "text": "parallel input impedance.", "correct": true}, {"id": "c", "text": "size of S.D.I.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'One of the ARINC 429 formats is', '[{"id": "a", "text": "BCD.", "correct": true}, {"id": "b", "text": "octal.", "correct": false}, {"id": "c", "text": "hexadecimal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A group of bits transmitted at the same time is', '[{"id": "a", "text": "parallel data.", "correct": true}, {"id": "b", "text": "a clock signal.", "correct": false}, {"id": "c", "text": "serial data.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The ARINC 429 system uses which of the following system to transfer data?', '[{"id": "a", "text": "Harvard bi-phase.", "correct": false}, {"id": "b", "text": "Bi-polar return to zero.", "correct": true}, {"id": "c", "text": "Non return to zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following ARINCs is bidirectional?', '[{"id": "a", "text": "629.", "correct": true}, {"id": "b", "text": "429.", "correct": false}, {"id": "c", "text": "573.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Data is transferred on the MIL-STD-1553B by using', '[{"id": "a", "text": "non return to zero.", "correct": false}, {"id": "b", "text": "Manchester bi-phase.", "correct": true}, {"id": "c", "text": "bipolar return to zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The general arrangement of ARINC 629 includes', '[{"id": "a", "text": "databus cable, current mode coupler, stub cable.", "correct": true}, {"id": "b", "text": "current mode coupler, databus cable only.", "correct": false}, {"id": "c", "text": "databus cable, stub cable, voltage mode coupler.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ARINC 629 Databus cables are terminated using', '[{"id": "a", "text": "100 ohms resistor.", "correct": false}, {"id": "b", "text": "130 ohms resistor.", "correct": true}, {"id": "c", "text": "25 ohms resistor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In ARINC 429 data field is bits 11 to 28. If the bits 11 to 18 had pad bits, the L.S.B. of the data would', '[{"id": "a", "text": "bit 19.", "correct": true}, {"id": "b", "text": "bit 28.", "correct": false}, {"id": "c", "text": "bit 11.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The BCD data field of ARINC 429 is contained within bits', '[{"id": "a", "text": "11-29.", "correct": true}, {"id": "b", "text": "11-28.", "correct": false}, {"id": "c", "text": "1-8.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ARINC 629 is transmitted using', '[{"id": "a", "text": "single wire for each transmitter.", "correct": false}, {"id": "b", "text": "fibre optics or twisted pair of wires.", "correct": true}, {"id": "c", "text": "SWG 28 wire.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A simplex system has', '[{"id": "a", "text": "1 transmitter and multiple receivers.", "correct": true}, {"id": "b", "text": "1 bus controller and 1 remote terminal.", "correct": false}, {"id": "c", "text": "1 bus controller and multiple receivers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'To create a bi-directional communications link within an ARINC 429 system', '[{"id": "a", "text": "four databuses are required.", "correct": false}, {"id": "b", "text": "only one databus is required.", "correct": false}, {"id": "c", "text": "two databuses are required.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Why does an ARINC databus system send data to LRUs in series?', '[{"id": "a", "text": "Saves weight.", "correct": true}, {"id": "b", "text": "More information can be sent.", "correct": false}, {"id": "c", "text": "Takes less time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Can an LRU transmit and receive on more than one 629 bus?', '[{"id": "a", "text": "Yes.", "correct": true}, {"id": "b", "text": "Only if paralleled.", "correct": false}, {"id": "c", "text": "No.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ARINC 629 LRUs transmit', '[{"id": "a", "text": "when addressed.", "correct": false}, {"id": "b", "text": "when signal gap is sensed.", "correct": false}, {"id": "c", "text": "when terminal gap is sensed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC 429 BCD word occupies bits 11-29, if 11-15 are filled with padders then the LSB of the word will be', '[{"id": "a", "text": "11.", "correct": false}, {"id": "b", "text": "16.", "correct": true}, {"id": "c", "text": "29.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A simplex system has', '[{"id": "a", "text": "one transmitter, many receivers.", "correct": true}, {"id": "b", "text": "a bus controller and separate controller.", "correct": false}, {"id": "c", "text": "one transmitter, one receiver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In an Arinc 429 Word label-representing heading is 320, this is represented in bits 1- 8 as', '[{"id": "a", "text": "01011001.", "correct": false}, {"id": "b", "text": "00001011.", "correct": true}, {"id": "c", "text": "01101000.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In ARINC 629 aperiodic mode, LRUs transmit in order of', '[{"id": "a", "text": "longest terminal gap to shortest terminal gap.", "correct": false}, {"id": "b", "text": "power up.", "correct": false}, {"id": "c", "text": "shortest terminal gap to longest terminal gap.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ARINC 629, aperiodic mode is used', '[{"id": "a", "text": "for landing and approach operation.", "correct": false}, {"id": "b", "text": "for normal operation.", "correct": false}, {"id": "c", "text": "for database loads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How is ARINC 429 bi-directional data transfer achieved?', '[{"id": "a", "text": "Via a current mode coupler.", "correct": false}, {"id": "b", "text": "Using two data buses.", "correct": true}, {"id": "c", "text": "Via a twisted pair of shielded cables.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The data format use to transmit signal to flight data recorder', '[{"id": "a", "text": "Harvard bi-phase 12 bit.", "correct": true}, {"id": "b", "text": "Bi-Polar RZ 12 bit.", "correct": false}, {"id": "c", "text": "Manchester 2 bi-phase 12 bit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The output voltage of ARINC 429 signal is', '[{"id": "a", "text": "-5v.", "correct": false}, {"id": "b", "text": "+10v to -10v.", "correct": true}, {"id": "c", "text": "+5v.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC 629 label word is', '[{"id": "a", "text": "10 bits.", "correct": false}, {"id": "b", "text": "12 bits.", "correct": true}, {"id": "c", "text": "8 bits.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The T/R of ARINC 629 is', '[{"id": "a", "text": "Encoder / decoder.", "correct": false}, {"id": "b", "text": "Multiplex / demultiplex.", "correct": true}, {"id": "c", "text": "switching.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Terminal gap in ARINC 629', '[{"id": "a", "text": "is always the same period.", "correct": false}, {"id": "b", "text": "is flexible.", "correct": false}, {"id": "c", "text": "can be changed by adjusting the rx/tx software.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How does ARINC 629 bus transmit and receive information?', '[{"id": "a", "text": "Sockets and pins.", "correct": false}, {"id": "b", "text": "Inductive coupling.", "correct": true}, {"id": "c", "text": "Optical coupling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is ARINC 561 used for?', '[{"id": "a", "text": "To specify LRU pin-outs.", "correct": false}, {"id": "b", "text": "To specify Radio Comms data bus.", "correct": true}, {"id": "c", "text": "To specify Flight Data Recorder data bus.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the purpose of the parity bit on an ARINC 429 bus?', '[{"id": "a", "text": "To indicate if the data is analogue.", "correct": false}, {"id": "b", "text": "To indicate that the data is digital.", "correct": false}, {"id": "c", "text": "To indicate to the receiver that the data is valid.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ARINC 429 is', '[{"id": "a", "text": "Single Source Multiple Sink System.", "correct": true}, {"id": "b", "text": "Multiple Source Multiple Sink system.", "correct": false}, {"id": "c", "text": "Single Source Single Sink system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Where is the parity bit installed in a data word?', '[{"id": "a", "text": "Front.", "correct": false}, {"id": "b", "text": "End MSB.", "correct": true}, {"id": "c", "text": "Middle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'RZ bi-polar modulation consists of bits which are one of __________ states?', '[{"id": "a", "text": "Eight.", "correct": false}, {"id": "b", "text": "Two.", "correct": false}, {"id": "c", "text": "Three.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In the ARINC 429 digital information transfer system, data may travel in:', '[{"id": "a", "text": "both directions on the same bus simultaneously.", "correct": false}, {"id": "b", "text": "one direction only.", "correct": true}, {"id": "c", "text": "both directions on the same bus sequentially by time multiplexing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ARINC 629 data word', '[{"id": "a", "text": "includes an 8 bit label and a 16 bit data field.", "correct": false}, {"id": "b", "text": "has only 20 bits.", "correct": true}, {"id": "c", "text": "comprises up to 256 data bits.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In an ARINC 429 digital word bit number 32 is used for', '[{"id": "a", "text": "terminating the data field.", "correct": false}, {"id": "b", "text": "checking parity.", "correct": true}, {"id": "c", "text": "identifying word type.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What connects an LRU to the Bus Coupler in an ARINC 629 Data Bus?', '[{"id": "a", "text": "Patch Cord.", "correct": false}, {"id": "b", "text": "Stub Cable.", "correct": true}, {"id": "c", "text": "Interconnect Cable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A 12 bit 16 Channel encoder will use a multiplexer with', '[{"id": "a", "text": "3 bit parallel address line.", "correct": false}, {"id": "b", "text": "4 bit parallel address line.", "correct": true}, {"id": "c", "text": "2 wire series address line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How many address lines would be needed for an 8 line MU?', '[{"id": "a", "text": "2.", "correct": false}, {"id": "b", "text": "3.", "correct": true}, {"id": "c", "text": "4.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a MU, how is parallel converted to serial?', '[{"id": "a", "text": "By way of a shift register.", "correct": true}, {"id": "b", "text": "By way of an encoder.", "correct": false}, {"id": "c", "text": "By way of a demultiplexer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A multiplexer', '[{"id": "a", "text": "takes many signals in and converts it to a serial transmission output.", "correct": true}, {"id": "b", "text": "takes many signals in and puts these in a parallel transmission on the output.", "correct": false}, {"id": "c", "text": "takes one signal in and converts it to a parallel transmission output.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A multiplexer in test equipment could be used for', '[{"id": "a", "text": "frequency divider.", "correct": true}, {"id": "b", "text": "analogue to digital converter.", "correct": false}, {"id": "c", "text": "digital to analogue converter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An 8 data input multiplexer has how many Data Select lines?', '[{"id": "a", "text": "8.", "correct": false}, {"id": "b", "text": "3.", "correct": true}, {"id": "c", "text": "2.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The signal sent between a MU/DEMU is controlled by', '[{"id": "a", "text": "clock.", "correct": false}, {"id": "b", "text": "the ALU.", "correct": false}, {"id": "c", "text": "control unit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Some of the advantages of fibre optic cable over copper cables are', '[{"id": "a", "text": "non conductive, easy to manufacture and assemble, more robust, cheap.", "correct": false}, {"id": "b", "text": "smaller in size and weight, non conductive, higher security and higher bandwidth.", "correct": true}, {"id": "c", "text": "non conductive, smaller in size and weight, easy to manufacture and assemble and higher security.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A fibre optic cable consists of', '[{"id": "a", "text": "a silica glass core with a cladding having a lower refractive index.", "correct": true}, {"id": "b", "text": "a silica glass core with a cladding having a higher refractive index.", "correct": false}, {"id": "c", "text": "a plastic core with a cladding having a higher refractive index.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fibre optic cables', '[{"id": "a", "text": "are immune to EMI.", "correct": true}, {"id": "b", "text": "attenuate EMI.", "correct": false}, {"id": "c", "text": "are susceptible to EMI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Two connected fibre optic cable ends are parallel but not quite touching. This is called', '[{"id": "a", "text": "end to end coupling.", "correct": false}, {"id": "b", "text": "lens connector.", "correct": false}, {"id": "c", "text": "end fire coupling. ← corrected answer", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A disadvantage of a fibre optic cable is', '[{"id": "a", "text": "couplings susceptible to ingress of fluid.", "correct": false}, {"id": "b", "text": "end terminals are susceptible to environmental contamination.", "correct": true}, {"id": "c", "text": "shallow bend radius allowed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What kind of light is used in a fibre optic systems?', '[{"id": "a", "text": "Infrared.", "correct": true}, {"id": "b", "text": "Visible.", "correct": false}, {"id": "c", "text": "Ultraviolet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fibreoptic data is sent by', '[{"id": "a", "text": "modulating the frequency of a laser beam. ← corrected answer", "correct": true}, {"id": "b", "text": "a strobe light. modulating the frequency of a filament beam.", "correct": false}, {"id": "c", "text": "Why: The source is a laser diode or LED whose output is modulated to carry the data. A strobe light is neither coherent nor", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'HIRF is prevented from entering a fibre optic cable by', '[{"id": "a", "text": "using an opto-isolator coupling.", "correct": true}, {"id": "b", "text": "grounding the fibre at both ends.", "correct": false}, {"id": "c", "text": "enclosing it in a metal braid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Continuity of a fibreoptic cable is checked by', '[{"id": "a", "text": "a calibrated light source.", "correct": false}, {"id": "b", "text": "a calibrated light source and an opto-power meter.", "correct": true}, {"id": "c", "text": "a light source and an opto-power meter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A fibreoptic data bus used on an aircraft', '[{"id": "a", "text": "can send only one message at a time.", "correct": false}, {"id": "b", "text": "can transmit on several channels at the same time.", "correct": true}, {"id": "c", "text": "connects non-essential systems only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Light travels along a fibre optic by', '[{"id": "a", "text": "refraction.", "correct": false}, {"id": "b", "text": "reflection.", "correct": true}, {"id": "c", "text": "dispersion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A typical fibre optic connector is', '[{"id": "a", "text": "F-type connector.", "correct": false}, {"id": "b", "text": "coupling type, with lens fitted.", "correct": true}, {"id": "c", "text": "push-pull connector.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following is an optoelectronic device?', '[{"id": "a", "text": "Triac.", "correct": false}, {"id": "b", "text": "Laser Diode.", "correct": true}, {"id": "c", "text": "Thyristor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the advantage of a single mode fibreoptic over ordinary wire?', '[{"id": "a", "text": "Not prone to damage.", "correct": false}, {"id": "b", "text": "Large bandwidth.", "correct": true}, {"id": "c", "text": "Small bend radius.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A fibreoptic light source is normally', '[{"id": "a", "text": "a strobe light.", "correct": false}, {"id": "b", "text": "a filament lamp.", "correct": false}, {"id": "c", "text": "a laser or LED.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The fibreoptic cable can be identified on aircraft by its jacket colour which is', '[{"id": "a", "text": "purple.", "correct": true}, {"id": "b", "text": "yellow.", "correct": false}, {"id": "c", "text": "red.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For a fibre optic cable connector that is not regularly disconnected you would use the', '[{"id": "a", "text": "butt type.", "correct": true}, {"id": "b", "text": "ball lens type.", "correct": false}, {"id": "c", "text": "ceramic lens type.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What maintenance problems are associated with fibreoptics?', '[{"id": "a", "text": "Corrosion.", "correct": false}, {"id": "b", "text": "Kinking and contamination of connectors.", "correct": true}, {"id": "c", "text": "Earthing faults.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A fibreoptic data bus', '[{"id": "a", "text": "can transmit several messages simultaneously.", "correct": true}, {"id": "b", "text": "is only used for non essential messages.", "correct": false}, {"id": "c", "text": "can only transmit 1 message at a time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A fiberoptic cable to LRU connector should be connected', '[{"id": "a", "text": "very carefully to ensure alignment and reduce light loss.", "correct": true}, {"id": "b", "text": "using torque-loaded pliers.", "correct": false}, {"id": "c", "text": "hand tight only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Some of the advantages of fibreoptic cable over copper cable are', '[{"id": "a", "text": "non conductive, higher bandwidth, higher security, smaller size and weight.", "correct": true}, {"id": "b", "text": "non conductive, easy to manufacture and assemble, higher bandwidth.", "correct": false}, {"id": "c", "text": "smaller size and weight, non conductive, more rugged, higher security.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a single mode fibreoptic cable', '[{"id": "a", "text": "several waves travel down the cable.", "correct": false}, {"id": "b", "text": "the diameter of the cable is dependent on the wavelength of the light used.", "correct": true}, {"id": "c", "text": "the distortion of the signal is dependent on the length of cable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A semiconductor which emits photons and releases electrons when stimulated by photons is called', '[{"id": "a", "text": "a photodiode.", "correct": false}, {"id": "b", "text": "a laser diode.", "correct": true}, {"id": "c", "text": "an LED.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What does a fibreoptic star connection do?', '[{"id": "a", "text": "Provides a continuous loop of fibre interconnecting all nodes.", "correct": false}, {"id": "b", "text": "Provides direct point-to-point services to units on dedicated lines emanating from the central hub.", "correct": true}, {"id": "c", "text": "Shares a common bandwidth of a common cable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A fibreoptic lens type coupling with lens and integral LED compared to an end-fire coupling is', '[{"id": "a", "text": "more efficient.", "correct": true}, {"id": "b", "text": "less efficient.", "correct": false}, {"id": "c", "text": "equally efficient.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Optical fibre losses are due to', '[{"id": "a", "text": "absorption only.", "correct": false}, {"id": "b", "text": "absorption, scattering and reflection.", "correct": true}, {"id": "c", "text": "radiation, absorption and reflection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The cone of acceptance is measured between', '[{"id": "a", "text": "longitudinal axis of the core and the outer angle.", "correct": false}, {"id": "b", "text": "longitudinal axis of the core and the inner angle.", "correct": false}, {"id": "c", "text": "the two outer angles. ← corrected answer", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fibreoptic cables use', '[{"id": "a", "text": "refractive outer shell.", "correct": true}, {"id": "b", "text": "reflective inner shell.", "correct": false}, {"id": "c", "text": "reflective outer shell.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In fibreoptic cable, signals are separated by', '[{"id": "a", "text": "active optic filter.", "correct": true}, {"id": "b", "text": "low pass filter.", "correct": false}, {"id": "c", "text": "passive optic filter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Most fibreoptic connectors are designed so', '[{"id": "a", "text": "the receptacle has to be torqued to a designated value to ensure correct alignment.", "correct": false}, {"id": "b", "text": "the connectors can not be over tightened.", "correct": true}, {"id": "c", "text": "the connector can not be replaced on the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The light source used in fibreoptics is', '[{"id": "a", "text": "visible light.", "correct": false}, {"id": "b", "text": "lower bandwidth than visible light.", "correct": true}, {"id": "c", "text": "higher bandwidth than visible light.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Light transmission in a fibreoptic cable is due to', '[{"id": "a", "text": "repeated internal reflection.", "correct": true}, {"id": "b", "text": "defraction of the light.", "correct": false}, {"id": "c", "text": "refraction of the light.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The name given to the joining of two fibreoptic cables by aligning them carefully and bringing them into close proximity of each other is', '[{"id": "a", "text": "Fusion.", "correct": false}, {"id": "b", "text": "Lens Coupling.", "correct": false}, {"id": "c", "text": "End to end.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a fibreoptic cable', '[{"id": "a", "text": "multiple data signals can be sent down it at one time.", "correct": true}, {"id": "b", "text": "data can only be sent in one direction.", "correct": false}, {"id": "c", "text": "only one data signal can be sent down it at any one time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fibreoptics relies on', '[{"id": "a", "text": "fibre absorbing light.", "correct": false}, {"id": "b", "text": "light escaping cladding.", "correct": false}, {"id": "c", "text": "light reflecting off cladding.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The light emitted from a LED used within a fibre-optic system will have a wavelength', '[{"id": "a", "text": "slightly shorter then that of visible light.", "correct": false}, {"id": "b", "text": "equal to that of visible light.", "correct": false}, {"id": "c", "text": "slightly longer then that of visible light.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Sensors in a fibreoptic flight control system', '[{"id": "a", "text": "require processing to give output.", "correct": false}, {"id": "b", "text": "does not require power.", "correct": false}, {"id": "c", "text": "require power for processors.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fibreoptic systems can transmit data in', '[{"id": "a", "text": "in two directions.", "correct": false}, {"id": "b", "text": "both directions at the same time.", "correct": true}, {"id": "c", "text": "one direction only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For high bandwidth high-speed fibreoptic transmission what sort of cable would you use?', '[{"id": "a", "text": "Step index.", "correct": false}, {"id": "b", "text": "Single mode.", "correct": true}, {"id": "c", "text": "Graded index.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In fibreoptics the wavelength of the light is', '[{"id": "a", "text": "more than visible light.", "correct": true}, {"id": "b", "text": "equal to that of visible light.", "correct": false}, {"id": "c", "text": "less than visible light.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the advantage of an ILD over an LED when used as a light source in fibre optics?', '[{"id": "a", "text": "Lower frequency range.", "correct": false}, {"id": "b", "text": "Lower intensity.", "correct": false}, {"id": "c", "text": "Higher bandwidth. ← corrected answer", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Speed of light in a fibreoptic fibre', '[{"id": "a", "text": "increases if it passes through material of higher refractive index.", "correct": false}, {"id": "b", "text": "is always the same no matter what material it is.", "correct": false}, {"id": "c", "text": "is never greater then the speed of light in free space.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The angle of incidence of a beam of light in a fibreoptic cable will be', '[{"id": "a", "text": "twice that of the cone of acceptance.", "correct": false}, {"id": "b", "text": "approximately half that of the cone of acceptance.", "correct": true}, {"id": "c", "text": "parallel with the end of the cable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In an optical fibre, the angle of acceptance is', '[{"id": "a", "text": "1/2 the signal wavelength.", "correct": false}, {"id": "b", "text": "equal to the cone of acceptance.", "correct": false}, {"id": "c", "text": "1/2 the cone of acceptance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When using a TDR (time delay reflectometer) the loss value of the cable is', '[{"id": "a", "text": "shown by the curve on the screen.", "correct": true}, {"id": "b", "text": "set on the TDR.", "correct": false}, {"id": "c", "text": "allowed for in the calculation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Common aircraft fibreoptics use', '[{"id": "a", "text": "modulating intensity on direct read.", "correct": true}, {"id": "b", "text": "modulating intensity on indirect read.", "correct": false}, {"id": "c", "text": "modulating frequency on direct read.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the main cause of attenuation in fibreoptics?', '[{"id": "a", "text": "Poor termination.", "correct": true}, {"id": "b", "text": "Refractive index.", "correct": false}, {"id": "c", "text": "Bends in the cable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the advantage of a laser diode over an LED?', '[{"id": "a", "text": "Greater bandwidth.", "correct": false}, {"id": "b", "text": "Narrower bandwidth.", "correct": true}, {"id": "c", "text": "There are no advantages.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A type A fibre optic connector', '[{"id": "a", "text": "is used when regular disconnection and re-connection of a cable is required.", "correct": false}, {"id": "b", "text": "produces a larger light loss that a type B connector.", "correct": false}, {"id": "c", "text": "would be used for connections not regularly disconnected.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The inside of a CRT consists of', '[{"id": "a", "text": "an oxide coating and rare mercury gas.", "correct": false}, {"id": "b", "text": "a phosphor coating and rare mercury gas.", "correct": true}, {"id": "c", "text": "iodine and rare mercury gas.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'CRT horizontal beam control is achieved by a', '[{"id": "a", "text": "sinusoidal wave.", "correct": false}, {"id": "b", "text": "square wave.", "correct": false}, {"id": "c", "text": "sawtooth wave.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a CRT, if the magnetic field is parallel to the Y plates, what will be the direction of the electron beam movement?', '[{"id": "a", "text": "Horizontal.", "correct": false}, {"id": "b", "text": "Vertical.", "correct": true}, {"id": "c", "text": "No movement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Primary colours of a CRT are', '[{"id": "a", "text": "red, green and yellow.", "correct": false}, {"id": "b", "text": "red, blue and yellow.", "correct": false}, {"id": "c", "text": "red, green and blue.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What are the effects of the X and Y plates on a CRT?', '[{"id": "a", "text": "Y plates move the beam vertically, X plates move the beam horizontally.", "correct": true}, {"id": "b", "text": "X plates move the beam vertically, Y plates move the beam horizontally.", "correct": false}, {"id": "c", "text": "X and Y plates can move the beam in either direction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'EADI sky and ground display is provided by', '[{"id": "a", "text": "synthetic TV signals.", "correct": false}, {"id": "b", "text": "stroke pulse.", "correct": false}, {"id": "c", "text": "raster scan.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What frequency creates the raster effect on a CRT?', '[{"id": "a", "text": "50/60 Hz.", "correct": true}, {"id": "b", "text": "250Hz.", "correct": false}, {"id": "c", "text": "400 Hz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The sweep waveform used on a electromagnetic CRT is', '[{"id": "a", "text": "trapezoidal.", "correct": true}, {"id": "b", "text": "sinusoidal.", "correct": false}, {"id": "c", "text": "sawtooth.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What shape does the waveform take to counter the impedance effect of the coils in an electromagnetic controlled CRT?', '[{"id": "a", "text": "Sawtooth.", "correct": false}, {"id": "b", "text": "Rectangular.", "correct": false}, {"id": "c", "text": "Trapezoid.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Magnetic deflection in a CRT is achieved by', '[{"id": "a", "text": "a sawtooth waveform.", "correct": false}, {"id": "b", "text": "a trapezoidal waveform.", "correct": true}, {"id": "c", "text": "a sinusoidal voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The timebase in a CRT consists of', '[{"id": "a", "text": "an amplifier and an oscillator.", "correct": true}, {"id": "b", "text": "an oscillator only.", "correct": false}, {"id": "c", "text": "an amplifier only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What creates the raster effect on a CRT?', '[{"id": "a", "text": "Sawtooth frequency.", "correct": true}, {"id": "b", "text": "Trapezoidal frequency.", "correct": false}, {"id": "c", "text": "Sinusoidal frequency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'LCD screens are driven by', '[{"id": "a", "text": "AC voltage.", "correct": true}, {"id": "b", "text": "variable current DC voltage.", "correct": false}, {"id": "c", "text": "fixed current DC voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A Liquid Crystal Display (LCD) has the advantage over a CRT that', '[{"id": "a", "text": "it requires no cooling.", "correct": true}, {"id": "b", "text": "it displays more colours.", "correct": false}, {"id": "c", "text": "it requires less servicing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The release of a photon by another photon is the principle of', '[{"id": "a", "text": "a photo diode.", "correct": false}, {"id": "b", "text": "a zener diode.", "correct": false}, {"id": "c", "text": "an LED.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If a magnetic field is parallel to the X plates in a CRT, which way will the beam move?', '[{"id": "a", "text": "Vertically.", "correct": false}, {"id": "b", "text": "Horizontally.", "correct": true}, {"id": "c", "text": "Diagonally.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An LED display is', '[{"id": "a", "text": "monochrome only.", "correct": true}, {"id": "b", "text": "red and green.", "correct": false}, {"id": "c", "text": "high definition.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An LCD display uses what type of power supply?', '[{"id": "a", "text": "DC voltage.", "correct": false}, {"id": "b", "text": "Continuous AC.", "correct": true}, {"id": "c", "text": "Variable level DC voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A beam deflection on EFIS displays are', '[{"id": "a", "text": "electrostatic.", "correct": false}, {"id": "b", "text": "electromagnetic.", "correct": true}, {"id": "c", "text": "solid state.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The supply to an LCD is', '[{"id": "a", "text": "AC.", "correct": true}, {"id": "b", "text": "current restricted DC.", "correct": false}, {"id": "c", "text": "voltage restricted DC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An LED will emit light when', '[{"id": "a", "text": "it is reverse biased.", "correct": false}, {"id": "b", "text": "either forward or reverse biased if a sufficient level of ac voltage is applied.", "correct": false}, {"id": "c", "text": "it is forward biased.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A CRT display has the advantage over an LCD display of a', '[{"id": "a", "text": "brighter clearer output.", "correct": false}, {"id": "b", "text": "more energy efficient.", "correct": false}, {"id": "c", "text": "large viewing angle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'To display a circle on a CRT you use', '[{"id": "a", "text": "2 square wave 90 degrees out of phase.", "correct": false}, {"id": "b", "text": "2 sine waves 180 degrees out of phase.", "correct": false}, {"id": "c", "text": "2 sine waves 90 degrees out of phase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'To deflect the beam of a CRT horizontally, coils are placed on the neck of the tube', '[{"id": "a", "text": "top and bottom.", "correct": true}, {"id": "b", "text": "one on the side, one at the bottom.", "correct": false}, {"id": "c", "text": "left and right.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If the magnetic deflection plates produce a magnetic field which is parallel to the horizontal then the trace is deflected in', '[{"id": "a", "text": "circular motion.", "correct": false}, {"id": "b", "text": "horizontal axis.", "correct": false}, {"id": "c", "text": "vertical axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The most common CRT control for an EFIS system screen is', '[{"id": "a", "text": "a combined system.", "correct": true}, {"id": "b", "text": "an electrostatic system.", "correct": false}, {"id": "c", "text": "an electromagnetic system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'L.E.D.s can give', '[{"id": "a", "text": "high definition displays.", "correct": false}, {"id": "b", "text": "monochrome displays only.", "correct": true}, {"id": "c", "text": "red and green displays only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'At low ambient temperatures, an LCD screen', '[{"id": "a", "text": "is slower to update as data changes.", "correct": true}, {"id": "b", "text": "viewing angle becomes larger.", "correct": false}, {"id": "c", "text": "loses contrast.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Colour CRT shadow mask screen resolution is', '[{"id": "a", "text": "400 lines per square inch.", "correct": false}, {"id": "b", "text": "84 triads.", "correct": true}, {"id": "c", "text": "600 lines per scan.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An LCD display', '[{"id": "a", "text": "has three colours only.", "correct": true}, {"id": "b", "text": "is monochrome.", "correct": false}, {"id": "c", "text": "has infinite colours.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A segmented configuration for the display of alphanumeric data requires', '[{"id": "a", "text": "the starburst display for numbers and lower case letters only.", "correct": false}, {"id": "b", "text": "16 segments to display the full range of capital letters and numerals.", "correct": true}, {"id": "c", "text": "at least 13 segments for all upper and lower case letters.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Electronic CRT beam display is used typically in', '[{"id": "a", "text": "weather radar indicators.", "correct": true}, {"id": "b", "text": "IRU control display units.", "correct": false}, {"id": "c", "text": "distance measuring indicators; digital counters.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a colour cathode ray tube, how is the phosphor arranged in the tube?', '[{"id": "a", "text": "A red layer on the front with two green layers behind it.", "correct": false}, {"id": "b", "text": "A single phosphor layer containing red, green and blue.", "correct": true}, {"id": "c", "text": "Layers of red, blue and green.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A colour LCD which is back lit has', '[{"id": "a", "text": "three colours.", "correct": true}, {"id": "b", "text": "monochrome.", "correct": false}, {"id": "c", "text": "an infinite amount of colours.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A dot matrix/LED construction is', '[{"id": "a", "text": "4*7 or a 9*5 rolling end display.", "correct": false}, {"id": "b", "text": "5*9 or a 4*7 rolling end display.", "correct": false}, {"id": "c", "text": "4*7 or a 5*7 rolling end display. ← corrected answer", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What are the advantages of an LCD display over an LED?', '[{"id": "a", "text": "It is brighter.", "correct": false}, {"id": "b", "text": "It uses less current.", "correct": true}, {"id": "c", "text": "There are no advantages.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A seven segment display is used to', '[{"id": "a", "text": "display alpha-numeric characters.", "correct": false}, {"id": "b", "text": "display octal and decimal numbers only.", "correct": true}, {"id": "c", "text": "display octal and binary numbers only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How are Alphanumeric Displays produced on a CRT?', '[{"id": "a", "text": "By Stroke pulse.", "correct": true}, {"id": "b", "text": "Raster scanning.", "correct": false}, {"id": "c", "text": "by the use of X & Y EM Coils.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The Shorter lead near the Flat portion of an LED is the', '[{"id": "a", "text": "Cathode.", "correct": true}, {"id": "b", "text": "Anode.", "correct": false}, {"id": "c", "text": "Gate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Submarining is', '[{"id": "a", "text": "caused by the inability of some LCD screens to respond to fast moving images on screen.", "correct": true}, {"id": "b", "text": "a CRT screen defect which can usually be remedied by degaussing the screen.", "correct": false}, {"id": "c", "text": "the process used to form liquid crystals into a flat screen.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ESDS bags are sealed by', '[{"id": "a", "text": "ESDS labels.", "correct": false}, {"id": "b", "text": "zip locks.", "correct": false}, {"id": "c", "text": "twine (100% cotton).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What precautions are required when removing ESDS equipment?', '[{"id": "a", "text": "Wear a wrist strap connected to an approved ground point.", "correct": true}, {"id": "b", "text": "No special precautions are required.", "correct": false}, {"id": "c", "text": "Keep one hand on the airframe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A flight deck CRT LRU is being replaced. What does the ESDS label indicate?', '[{"id": "a", "text": "Wrist straps should be worn.", "correct": false}, {"id": "b", "text": "Do not touch plug pins or leave them exposed.", "correct": true}, {"id": "c", "text": "Remove power before connecting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'During an EFIS screen fit', '[{"id": "a", "text": "dont touch terminals.", "correct": true}, {"id": "b", "text": "no tooling is required.", "correct": false}, {"id": "c", "text": "use bonding strap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'With a relative humidity of 10% to 20%, if you walked over a carpet what electrostatic voltage value would you expect to see?', '[{"id": "a", "text": "35,000 volts.", "correct": true}, {"id": "b", "text": "6,000 volts.", "correct": false}, {"id": "c", "text": "12,000 volts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Before fitting a Printed Circuit Board you should check the', '[{"id": "a", "text": "resistance between skin and strap end plug is less than 10 megohms. ← corrected answer", "correct": true}, {"id": "b", "text": "resistance between skin and strap end plug is more than 1 megohms.", "correct": false}, {"id": "c", "text": "resistance between strap and strap end plug is less than 1 megohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The resistance of the wrist strap used as part of anti -static precautions should be', '[{"id": "a", "text": "0 - 200 ohm.", "correct": false}, {"id": "b", "text": "20 megohm - 200 megohm.", "correct": false}, {"id": "c", "text": "250 kilohm - 1.5 megohm.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When handling PCB labelled ESDS, what precaution are taken?', '[{"id": "a", "text": "Do not touch its pins as copper contamination can occur.", "correct": false}, {"id": "b", "text": "Isolate electrical power before installing on Aircraft.", "correct": true}, {"id": "c", "text": "First earth with aircraft then to it.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'After attaching a wrist strap to your wrist (which is connected to aircraft ground), prior to removal of ESDS equipment, the resistance measured', '[{"id": "a", "text": "between your skin and the pin ground must be >1 megohms.", "correct": false}, {"id": "b", "text": "between the strap and the pin ground must be <1 megohms.", "correct": false}, {"id": "c", "text": "between the strap and the pin ground must be >1 Megohms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following ESDS devices can withstand higher static electricity voltage?', '[{"id": "a", "text": "MOSFET.", "correct": false}, {"id": "b", "text": "SCR.", "correct": true}, {"id": "c", "text": "ECL.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A wrist band must be worn when working with ESDS devices', '[{"id": "a", "text": "to dissipate and prevent static build-up on the operator.", "correct": true}, {"id": "b", "text": "to prevent the operator from getting an electric shock.", "correct": false}, {"id": "c", "text": "to dissipate static charge on the device.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A humid atmosphere', '[{"id": "a", "text": "reduces static charge.", "correct": true}, {"id": "b", "text": "eliminates static charge.", "correct": false}, {"id": "c", "text": "has no effect on the level of charge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Electrostatic discharge occurs when', '[{"id": "a", "text": "the ground lead on a wrist strap touches the skin.", "correct": false}, {"id": "b", "text": "materials are rubbed together or pulled apart.", "correct": false}, {"id": "c", "text": "materials of different potential are brought in close proximity to each other.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Before removing an assembly from an aircraft, with regards to HIRF, you must first ensure that there is minimum current flow between', '[{"id": "a", "text": "the assembly and the aircraft.", "correct": false}, {"id": "b", "text": "you and the assembly.", "correct": true}, {"id": "c", "text": "you and the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When removing a PC card from an ESDS assembly ensure a low current path between', '[{"id": "a", "text": "aircraft and ground.", "correct": false}, {"id": "b", "text": "you and the assembly.", "correct": false}, {"id": "c", "text": "you and the aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An aircraft system that, should it fail due to a software error, would cause a significant reduction in safety margins may also cause', '[{"id": "a", "text": "no injuries to occupants.", "correct": false}, {"id": "b", "text": "injuries to some occupants.", "correct": true}, {"id": "c", "text": "the loss of the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An aircraft system allocated a software level of C that, should it fail due to a software error, may cause', '[{"id": "a", "text": "injuries to some occupants.", "correct": true}, {"id": "b", "text": "injuries to a large proportion of occupants.", "correct": false}, {"id": "c", "text": "no injuries to occupants.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An aircraft system allocated a Criticality Category of Hazardous has a Software Level of', '[{"id": "a", "text": "A.", "correct": false}, {"id": "b", "text": "B.", "correct": true}, {"id": "c", "text": "C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An aircraft system that, should it fail due to a software error, would cause a slight increase in crew workload, has a software level of', '[{"id": "a", "text": "B.", "correct": false}, {"id": "b", "text": "C.", "correct": false}, {"id": "c", "text": "D.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An aircraft system with a software level of D, should it fail due to a software error, may cause the aircraft safety margin to be', '[{"id": "a", "text": "slightly decreased.", "correct": true}, {"id": "b", "text": "slightly increased.", "correct": false}, {"id": "c", "text": "significantly decreased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If due to a software error in an aircraft system that would cause injuries to some of the occupants, the system has a software criticality category of', '[{"id": "a", "text": "major effect.", "correct": true}, {"id": "b", "text": "hazardous effect.", "correct": false}, {"id": "c", "text": "minor effect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An aircraft system that, should it fail due to a software error, would cause no injuries to occupants, has a criticality category of', '[{"id": "a", "text": "major effect.", "correct": false}, {"id": "b", "text": "minor effect.", "correct": true}, {"id": "c", "text": "hazardous effect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Requirements for software control can be found in', '[{"id": "a", "text": "JAR AWO.", "correct": false}, {"id": "b", "text": "AWN 43.", "correct": true}, {"id": "c", "text": "JAR OPS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Software can be modified by', '[{"id": "a", "text": "the manufacturer.", "correct": false}, {"id": "b", "text": "using the same rules as apply as to modifications to hardware.", "correct": true}, {"id": "c", "text": "licensed avionics engineers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Who is responsible for producing the operational program of the FMS?', '[{"id": "a", "text": "The manufacturer.", "correct": true}, {"id": "b", "text": "The pilot.", "correct": false}, {"id": "c", "text": "The engineer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Software documentation procedures are laid down in', '[{"id": "a", "text": "MOE.", "correct": false}, {"id": "b", "text": "JAA Ops.", "correct": false}, {"id": "c", "text": "AWN 45.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Control of software is carried out by', '[{"id": "a", "text": "the aircraft manufacturers.", "correct": false}, {"id": "b", "text": "a licensed engineer.", "correct": false}, {"id": "c", "text": "the National Aviation Authority.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the definition of level one software?', '[{"id": "a", "text": "Non-essential.", "correct": false}, {"id": "b", "text": "Essential.", "correct": false}, {"id": "c", "text": "Critical.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Who can sign for a software update?', '[{"id": "a", "text": "Design organization or the aircraft manufacturer.", "correct": false}, {"id": "b", "text": "Engineer.", "correct": true}, {"id": "c", "text": "Chief pilot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the effect of a level 1 software failure?', '[{"id": "a", "text": "Significant reduction in safety margins.", "correct": false}, {"id": "b", "text": "Large reduction in safety margins.", "correct": false}, {"id": "c", "text": "Loss of aircraft and / or fatalities.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Software changes come under the responsibility of', '[{"id": "a", "text": "the engineer.", "correct": false}, {"id": "b", "text": "the national aviation authority.", "correct": false}, {"id": "c", "text": "the aircraft constructor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Who can design new software?', '[{"id": "a", "text": "BCAR section A8 approved company.", "correct": true}, {"id": "b", "text": "BCAR section A1 approved company.", "correct": false}, {"id": "c", "text": "The CAA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'As far as a software product is concerned', '[{"id": "a", "text": "the \"Software Release\" phase is the same as the \"Finished Product\" phase.", "correct": false}, {"id": "b", "text": "the \"Validation\" phase is done to the software rather than to the component.", "correct": false}, {"id": "c", "text": "the \"Verification\" phase includes performance testing a programmed EPROM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'AWN 43 requires that', '[{"id": "a", "text": "the aircraft operator be responsible for software assessment.", "correct": false}, {"id": "b", "text": "the CAA be responsible for software assessment.", "correct": false}, {"id": "c", "text": "the aircraft constructors be responsible for software assessment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Level 1 software failure', '[{"id": "a", "text": "is defined as essential and will reduce safety margins.", "correct": false}, {"id": "b", "text": "is defined as essential and may have a minor effect.", "correct": false}, {"id": "c", "text": "is defined as critical and can lead to loss of aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Requirements for configuration management of software can be found in', '[{"id": "a", "text": "AWN 43.", "correct": true}, {"id": "b", "text": "PART M.", "correct": false}, {"id": "c", "text": "ATA Chapter 46, Information Systems.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Where would you find the rules regarding upgrade of software?', '[{"id": "a", "text": "JAR OPS.", "correct": false}, {"id": "b", "text": "The aircraft manufacturer.", "correct": false}, {"id": "c", "text": "AWN 43.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In order to maintain HIRF protection, bonding checks between airframe and electrical components carrying voltages greater than 50 volts RMS or DC or main earth return should not exceed', '[{"id": "a", "text": "1 megohm.", "correct": false}, {"id": "b", "text": "1 ohm", "correct": false}, {"id": "c", "text": "0.05 ohm.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Ribbon cables effected by mutual impedance and current loop leakage should be protected by', '[{"id": "a", "text": "earthing each alternative conductor to separate point.", "correct": true}, {"id": "b", "text": "connecting all conductors to a common earth.", "correct": false}, {"id": "c", "text": "shielding each individual conductor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'To shield a fibre optic from EMI you must', '[{"id": "a", "text": "earth both transducer and couplings.", "correct": false}, {"id": "b", "text": "shield it with a braided shield.", "correct": false}, {"id": "c", "text": "use an opto-isolator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Manufacturers of aircraft can ensure HIRF protection by', '[{"id": "a", "text": "advising operators of all points susceptible to deterioration due to corrosion, moisture ingress, flexing etc.", "correct": false}, {"id": "b", "text": "designing specific avionic areas that are shielded against HIRF.", "correct": true}, {"id": "c", "text": "ensuring all single wires are shielded with metal conduit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which of the following could be a primary cause of HIRF protection failure?', '[{"id": "a", "text": "Broken or missing static wicks.", "correct": false}, {"id": "b", "text": "Corrosion on bonding leads.", "correct": true}, {"id": "c", "text": "Unserviceable radio filters", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Manufacturers of aircraft can ensure HIRF protection', '[{"id": "a", "text": "by designing specific avionic areas that are shielded against HIRF.", "correct": true}, {"id": "b", "text": "by ensuring all single wires are shielded with metal conduit.", "correct": false}, {"id": "c", "text": "by advising the operator of parts of the aircraft susceptible to degradation due to corrosion, moisture ingress,", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'HIRF protection of LRUs is provided by', '[{"id": "a", "text": "internally shielded cables.", "correct": false}, {"id": "b", "text": "built in filters and overvoltage circuits.", "correct": true}, {"id": "c", "text": "built in filters only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'To stop earth loops forming, you would', '[{"id": "a", "text": "earth both ends of the cable screen.", "correct": false}, {"id": "b", "text": "leave both ends of the cable screen open circuit.", "correct": false}, {"id": "c", "text": "earth only one end of the cable screen.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An aircraft may have been HIRF affected.', '[{"id": "a", "text": "Test all radio frequencies for interference.", "correct": false}, {"id": "b", "text": "A static wick check is required.", "correct": false}, {"id": "c", "text": "A bonding load check is required.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Testing of HIRF on aircraft systems is done', '[{"id": "a", "text": "by periodically listening for interference on all systems.", "correct": false}, {"id": "b", "text": "at and during production and testing (initial certification).", "correct": true}, {"id": "c", "text": "only after a report of radio interference.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When carrying out a bonding check on a surface protected by anodic film', '[{"id": "a", "text": "the film is conductive so no preparations are required.", "correct": false}, {"id": "b", "text": "the anodic film should be removed locally to ensure a good contact.", "correct": true}, {"id": "c", "text": "add a bonding factor to the result of the test to account for the resistance of the anodic film.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When clamping cable looms containing co-axial cables', '[{"id": "a", "text": "avoid distortion to the co-axial cable to maintain the dielectric constant.", "correct": true}, {"id": "b", "text": "the clamps must be no more than 1 metre apart.", "correct": false}, {"id": "c", "text": "distortion of the outer sheath is allowed providing the inner cable is not affected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When incorporating an aerial cable it must be', '[{"id": "a", "text": "in the centre of the other wires.", "correct": false}, {"id": "b", "text": "outside the other wires for easy access.", "correct": false}, {"id": "c", "text": "positioned separately from the loom.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When carrying out airframe bonding checks as part of a program of HIRF prevention the airframe bonding resistance should be less than', '[{"id": "a", "text": "100 milliohms.", "correct": false}, {"id": "b", "text": "1 ohm.", "correct": false}, {"id": "c", "text": "50 milliohms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Electromagnetic compatibility is achieved by', '[{"id": "a", "text": "shielding, screening, earthing, bonding and interference filters.", "correct": true}, {"id": "b", "text": "coating in a conductive paint.", "correct": false}, {"id": "c", "text": "enclosing the system with same frequency and strength of which screening is done.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'To reduce HIRF on radio equipment', '[{"id": "a", "text": "ensure all static wicks are in place.", "correct": false}, {"id": "b", "text": "periodically check bonding leads for condition. ← corrected answer", "correct": true}, {"id": "c", "text": "transmit on all radio frequencies to determine which frequencies are causing the interference.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For braided cables, the amount of braiding', '[{"id": "a", "text": "must conform to the requirement for the shielding to cover at least 50% of the surface of the cable.", "correct": false}, {"id": "b", "text": "keeps radiated power inside the emitting assembly or away from the susceptible circuit.", "correct": true}, {"id": "c", "text": "is a trade-off design feature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'HIRF is acronym for', '[{"id": "a", "text": "Heavily Ionised Radio Frequencies.", "correct": false}, {"id": "b", "text": "High Intensity Radiated Field.", "correct": true}, {"id": "c", "text": "High Intensity Radio Frequencies.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'HF aerials are protected against lightning strike by', '[{"id": "a", "text": "current mode coupler.", "correct": false}, {"id": "b", "text": "bus terminal.", "correct": false}, {"id": "c", "text": "spark gap.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An FMS system, besides controlling navigation, thrust and auto-nav, also provides', '[{"id": "a", "text": "GPWS warnings.", "correct": false}, {"id": "b", "text": "dedicated status and warnings.", "correct": true}, {"id": "c", "text": "take-off and landing warnings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The minimum standards for aircraft instrumentation is set by', '[{"id": "a", "text": "CAA.", "correct": false}, {"id": "b", "text": "ICAO.", "correct": false}, {"id": "c", "text": "JAA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'EADI sky and ground display is provided by', '[{"id": "a", "text": "raster scan.", "correct": true}, {"id": "b", "text": "stroke pulse.", "correct": false}, {"id": "c", "text": "synthetic TV signals.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'HSI heading is valid if the heading flag is', '[{"id": "a", "text": "in view.", "correct": false}, {"id": "b", "text": "green.", "correct": false}, {"id": "c", "text": "out of view.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'MFD is the abbreviation for', '[{"id": "a", "text": "Multi function display.", "correct": true}, {"id": "b", "text": "Mandatory flight display.", "correct": false}, {"id": "c", "text": "Master flight display.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A TCAS uses the radar mile definition in its calculations, which is', '[{"id": "a", "text": "36 microsecond.", "correct": true}, {"id": "b", "text": "18 microsecond.", "correct": false}, {"id": "c", "text": "72 microsecond.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'GPS navigation uses a constellation of satellites that is made up of', '[{"id": "a", "text": "21 active and 3 spare.", "correct": true}, {"id": "b", "text": "28 active and 7 spare.", "correct": false}, {"id": "c", "text": "23 active and 5 spare.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An IRS is only certifed for alingment up to', '[{"id": "a", "text": "+88. 45 and -88.45 degrees.", "correct": false}, {"id": "b", "text": "+78. 25 and -78.25 degrees.", "correct": true}, {"id": "c", "text": "+60 and -60 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The command bars on an ADI relate to', '[{"id": "a", "text": "roll indications.", "correct": false}, {"id": "b", "text": "path being followed.", "correct": false}, {"id": "c", "text": "path required.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ECAM has at its heart', '[{"id": "a", "text": "a multi function symbol generator.", "correct": true}, {"id": "b", "text": "a central maintenance computer.", "correct": false}, {"id": "c", "text": "ACARS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The recording medium in an FDR is', '[{"id": "a", "text": "copper foil coated with ferrite.", "correct": false}, {"id": "b", "text": "a high density floppy disc.", "correct": false}, {"id": "c", "text": "magnetic tape coated with ferrite.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The recording medium in an FDR is', '[{"id": "a", "text": "copper foil coated with ferrite.", "correct": false}, {"id": "b", "text": "a high density floppy disc.", "correct": false}, {"id": "c", "text": "magnetic tape coated with ferrite.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An FMS databank memory is updated', '[{"id": "a", "text": "every 365 days.", "correct": false}, {"id": "b", "text": "every 28 days.", "correct": true}, {"id": "c", "text": "every 32 days.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What does the CADC feed?', '[{"id": "a", "text": "cabin pressure controller sensor / machmeter / altimeter.", "correct": true}, {"id": "b", "text": "Altimeter / FMS / secondary radar.", "correct": false}, {"id": "c", "text": "standby altimeter / machmeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a Flight Management System (FMS), data is input manually to the computing system through the', '[{"id": "a", "text": "Data Acquisition Unit.", "correct": false}, {"id": "b", "text": "Electronic Centralised Aircraft Monitoring control panel.", "correct": false}, {"id": "c", "text": "Control and Display Unit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a Global Positioning System (GPS), the number of satellites required to achieve a 3 dimensional fix is', '[{"id": "a", "text": "2.", "correct": false}, {"id": "b", "text": "3.", "correct": false}, {"id": "c", "text": "4.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a Global Positioning System (GPS), each satellite transmission identifies the satellite using a', '[{"id": "a", "text": "different channel frequency.", "correct": false}, {"id": "b", "text": "pseudo random code.", "correct": true}, {"id": "c", "text": "whisper shout method.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a Global Positioning System (GPS) satellites below the Mask Angle are ignored as these may cause', '[{"id": "a", "text": "range errors.", "correct": true}, {"id": "b", "text": "clock errors.", "correct": false}, {"id": "c", "text": "ephemeris errors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Information required by a Flight Management System (FMS) to function correctly is indicated on the display by', '[{"id": "a", "text": "dashes.", "correct": false}, {"id": "b", "text": "a flashing cursor.", "correct": false}, {"id": "c", "text": "boxes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A flight data recorder can obtain information from aircraft instruments', '[{"id": "a", "text": "provided there is adequate damping.", "correct": false}, {"id": "b", "text": "provided there is adequate isolation.", "correct": true}, {"id": "c", "text": "by direct connection to the instruments.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The inputs and outputs of a CADC are', '[{"id": "a", "text": "pitot and static in; altitude, attitude, CAS and VS out.", "correct": false}, {"id": "b", "text": "pitot and static in; altitude, CAS, mach and VS out.", "correct": true}, {"id": "c", "text": "pitot in; static, altitude, mach, CAS and VS out.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'EICAS provides the following:', '[{"id": "a", "text": "Engine parameters and engine warnings only.", "correct": false}, {"id": "b", "text": "Engine parameters and system warnings only.", "correct": true}, {"id": "c", "text": "Engine parameters only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A central maintenance computer provides', '[{"id": "a", "text": "ground and flight monitoring and testing on an on-board computer.", "correct": true}, {"id": "b", "text": "ground and BITE testing using a portable control panel.", "correct": false}, {"id": "c", "text": "display of system warnings and cautions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The rising runway is positioned from information derived from', '[{"id": "a", "text": "barometric height.", "correct": false}, {"id": "b", "text": "radio altimeter.", "correct": true}, {"id": "c", "text": "vertical speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Where are the Digital Flight Data Recorder outputs supplied to?', '[{"id": "a", "text": "The recording unit.", "correct": false}, {"id": "b", "text": "There are no outputs.", "correct": true}, {"id": "c", "text": "Flight instruments.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'FMS failure and warnings are', '[{"id": "a", "text": "EFIS warnings only.", "correct": false}, {"id": "b", "text": "displayed on EICAS.", "correct": true}, {"id": "c", "text": "engine warnings only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Flight director command bars are moved to the correct position by', '[{"id": "a", "text": "calibration.", "correct": false}, {"id": "b", "text": "position feedback.", "correct": true}, {"id": "c", "text": "amplifier gain.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What information is required before completion of the alignment of an Inertial Navigation System?', '[{"id": "a", "text": "Aircraft present position.", "correct": true}, {"id": "b", "text": "Heading and attitude.", "correct": false}, {"id": "c", "text": "Aircraft present position and heading.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'IRS accelerometers are mounted', '[{"id": "a", "text": "90Â° to each other.", "correct": true}, {"id": "b", "text": "45Â° to each other.", "correct": false}, {"id": "c", "text": "60Â° to each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An FMS navigation database is updated', '[{"id": "a", "text": "once a month.", "correct": false}, {"id": "b", "text": "every 28 days.", "correct": true}, {"id": "c", "text": "at the operators request.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A single failure of a fly-by-wire system', '[{"id": "a", "text": "will reduce operational heights and speeds.", "correct": false}, {"id": "b", "text": "will limit the flight profile.", "correct": false}, {"id": "c", "text": "has no effect on aircraft operation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fly-by-wire load alleviation function in turbulent conditions will result in', '[{"id": "a", "text": "spoilers moving symmetrically upwards.", "correct": false}, {"id": "b", "text": "ailerons moving symmetrically upwards.", "correct": false}, {"id": "c", "text": "ailerons and spoilers moving symmetrically upwards.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fly-by-wire roll control is achieved by', '[{"id": "a", "text": "spoilers and ailerons.", "correct": true}, {"id": "b", "text": "ailerons.", "correct": false}, {"id": "c", "text": "spoilers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The movement of fly-by-wire control surfaces are', '[{"id": "a", "text": "hydraulically controlled and electrically actuated.", "correct": false}, {"id": "b", "text": "both electrically controlled and electrically actuated.", "correct": false}, {"id": "c", "text": "electrically controlled and hydraulically actuated.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An FMS system, besides controlling navigation, thrust and auto-nav, also provides', '[{"id": "a", "text": "dedicated status warnings.", "correct": true}, {"id": "b", "text": "take-off and landing warnings.", "correct": false}, {"id": "c", "text": "GPWS warnings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If an EFIS has 3 symbol generators. What is the purpose of the 3rd symbol generator?', '[{"id": "a", "text": "Comparison with No.1 symbol generator.", "correct": false}, {"id": "b", "text": "Parity function.", "correct": false}, {"id": "c", "text": "Standby.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'FMS operational program is updated every', '[{"id": "a", "text": "90 days.", "correct": false}, {"id": "b", "text": "28 days.", "correct": true}, {"id": "c", "text": "7 days.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An FDR fitted to a helicopter begins recording', '[{"id": "a", "text": "when power is applied to the aircraft.", "correct": false}, {"id": "b", "text": "on take-off.", "correct": false}, {"id": "c", "text": "on engine start-up.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The FMS databases consist of', '[{"id": "a", "text": "one navigation and one performance database.", "correct": false}, {"id": "b", "text": "one performance and two navigation databases.", "correct": true}, {"id": "c", "text": "two performance and one navigation database.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The FMS can update the IRS position outputs by using information from either', '[{"id": "a", "text": "VOR and DME only.", "correct": false}, {"id": "b", "text": "GPS, DME, LOC and VOR.", "correct": true}, {"id": "c", "text": "DME and GPS only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The accepted error from INS/IRS is', '[{"id": "a", "text": "3 miles / hour + 3 miles.", "correct": true}, {"id": "b", "text": "2 miles per hour + 3 miles.", "correct": false}, {"id": "c", "text": "1 mile/hour+3 miles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Before an IRS can complete the alignment sequence', '[{"id": "a", "text": "the current present position must be entered.", "correct": true}, {"id": "b", "text": "either the last or current position must be entered.", "correct": false}, {"id": "c", "text": "the shutdown present position must be entered.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What warnings can an FMS provide?', '[{"id": "a", "text": "Discrete warnings.", "correct": true}, {"id": "b", "text": "Spurious faults.", "correct": false}, {"id": "c", "text": "Ground faults only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Electronic Centralised Aircraft Monitoring System', '[{"id": "a", "text": "performs in-flight and ground tests of aircraft systems by carrying out a BITE interrogation.", "correct": false}, {"id": "b", "text": "performs in-flight BITE interrogation only.", "correct": false}, {"id": "c", "text": "give red warnings and amber cautions to display system status.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The control of the speed or rate that the flight director command bars move can be controlled by', '[{"id": "a", "text": "position feedback.", "correct": false}, {"id": "b", "text": "rate or velocity feedback.", "correct": true}, {"id": "c", "text": "amplifier gain.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The Centralised Aircraft Monitoring System uses the maintenance mode of operation', '[{"id": "a", "text": "on the ground only.", "correct": true}, {"id": "b", "text": "in the air only.", "correct": false}, {"id": "c", "text": "either in the air or on the ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The third EFIS Symbol Generator is operated', '[{"id": "a", "text": "in an emergency.", "correct": false}, {"id": "b", "text": "with EICAS.", "correct": false}, {"id": "c", "text": "as a standby to the No1 and No2 system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'EFIS displays of the right hand and left hand displays are compared by comparators in the', '[{"id": "a", "text": "FMS.", "correct": false}, {"id": "b", "text": "EICAS.", "correct": false}, {"id": "c", "text": "Symbol Generators.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the approximate earth rate?', '[{"id": "a", "text": "10Â°/hour.", "correct": false}, {"id": "b", "text": "5Â°/hour.", "correct": false}, {"id": "c", "text": "15Â°/hour.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An IRS has', '[{"id": "a", "text": "two or three accelerometers depending on the system.", "correct": false}, {"id": "b", "text": "three accelerometers.", "correct": true}, {"id": "c", "text": "two accelerometers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'IRS Laser Ring Gyros provide', '[{"id": "a", "text": "rate of movement about an axis.", "correct": true}, {"id": "b", "text": "displacement about an axis.", "correct": false}, {"id": "c", "text": "both rate and displacement about an axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What are the outputs of a Digital ADC?', '[{"id": "a", "text": "TAS, MACH, Altitude and TAT.", "correct": false}, {"id": "b", "text": "TAS, MACH, Altitude, TAT and SAT.", "correct": true}, {"id": "c", "text": "TAS, MACH and Altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fly By Wire systems in the fully active mode, the actuators will', '[{"id": "a", "text": "both be active.", "correct": true}, {"id": "b", "text": "both be in damping mode, awaiting control inputs.", "correct": false}, {"id": "c", "text": "one in active mode, one in damping mode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On a Fly By Wire system, what controls the stab trim?', '[{"id": "a", "text": "ELAC and SEC.", "correct": true}, {"id": "b", "text": "SEC.", "correct": false}, {"id": "c", "text": "ELAC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The minimum requirement for a cockpit voice recorder to begin operating is', '[{"id": "a", "text": "on engine start-up.", "correct": true}, {"id": "b", "text": "on commencing the takeoff roll.", "correct": false}, {"id": "c", "text": "once established in the en-route climb.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Aircraft Communications Addressing and Reporting Systems is used to', '[{"id": "a", "text": "download aircraft status reports.", "correct": true}, {"id": "b", "text": "make telephone calls.", "correct": false}, {"id": "c", "text": "allow the pilot of an aircraft to talk to base.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'B-RNAV system must be capable of', '[{"id": "a", "text": "holding six waypoints.", "correct": false}, {"id": "b", "text": "displaying distance and bearing to waypoint.", "correct": true}, {"id": "c", "text": "reversing the waypoints for.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The basic principle of radar is based upon', '[{"id": "a", "text": "the amount of power in the signal returned.", "correct": false}, {"id": "b", "text": "the time delay between outward and returning pulse.", "correct": true}, {"id": "c", "text": "ultrasonic wave propagation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What systems does the ADC feed?', '[{"id": "a", "text": "Altimeter / FMS / secondary radar.", "correct": false}, {"id": "b", "text": "Cabin pressure controller sensor / machmeter / Altimeter.", "correct": true}, {"id": "c", "text": "Standby altimeter/machmeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which systems does a modern ADC give information to?', '[{"id": "a", "text": "EFIS.", "correct": false}, {"id": "b", "text": "EICAS.", "correct": false}, {"id": "c", "text": "Flight control computer, Air Data Instrument, Engine systems.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Where do the outputs from a DADC go?', '[{"id": "a", "text": "EHSI.", "correct": false}, {"id": "b", "text": "EADI.", "correct": true}, {"id": "c", "text": "IRMP: Inertial Reference Mode Panel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How many satellite signals are required to achieve precise 3D positioning?', '[{"id": "a", "text": "4.", "correct": true}, {"id": "b", "text": "5.", "correct": false}, {"id": "c", "text": "6.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The minimum requirement for an aeroplane CVR is', '[{"id": "a", "text": "from power on.", "correct": false}, {"id": "b", "text": "from engine start.", "correct": true}, {"id": "c", "text": "from beginning of take off roll.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An Inertial Navigation System (INS/IRS) computes distance from acceleration by', '[{"id": "a", "text": "two successive integrations.", "correct": true}, {"id": "b", "text": "a simple integration.", "correct": false}, {"id": "c", "text": "a differentiation followed by an integration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Before the aircraft is moved from the loading pier the pilot must', '[{"id": "a", "text": "insert the longitude and latitude of the first waypoint into the INS.", "correct": false}, {"id": "b", "text": "set the altitude to be fed into the INS.", "correct": false}, {"id": "c", "text": "insert the latitude and longitude of the pier into the IRS.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An IRS has', '[{"id": "a", "text": "accelerometers and gyros fixed to a the airframe.", "correct": true}, {"id": "b", "text": "accelerometers fixed to the airframe and gyros on a stable platform.", "correct": false}, {"id": "c", "text": "accelerometers on a stable platform and gyros fixed to the airframe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An IRS system requires data for wind computation from', '[{"id": "a", "text": "Doppler System.", "correct": false}, {"id": "b", "text": "satellites.", "correct": false}, {"id": "c", "text": "central Air Data Computer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The FMS carries out a Rho/Theta navigation function, the purpose of this is to', '[{"id": "a", "text": "update the IRS system with an accurate position fix of latitude and longitude.", "correct": true}, {"id": "b", "text": "to update the VOR and DME systems with an accurate position fix.", "correct": false}, {"id": "c", "text": "to update the EMS with the new lateral flight profile for the flight plan.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The FMS is updated', '[{"id": "a", "text": "automatically by update data from the ACARS.", "correct": false}, {"id": "b", "text": "by an aircraft engineer updating the system either by a magnetic tape or floppy disc.", "correct": true}, {"id": "c", "text": "by the aircrew by reference to the Tech Log.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Pitch Control of a fly by wire system is achieved by', '[{"id": "a", "text": "stabilizer only.", "correct": false}, {"id": "b", "text": "elevators only.", "correct": false}, {"id": "c", "text": "stabilizer and elevator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a fly by wire system, if the pilot control input is derived from a side stick controller:', '[{"id": "a", "text": "there is no control surface feedback to the side stick.", "correct": true}, {"id": "b", "text": "control surface feedback is fed to the side stick.", "correct": false}, {"id": "c", "text": "there will be only control surface feedback to the side stick after a computer failure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A basic IRS platform has', '[{"id": "a", "text": "3 accelerometers and 2 laser gyros.", "correct": false}, {"id": "b", "text": "2 Accelerometers and 3 laser gyros.", "correct": false}, {"id": "c", "text": "3 accelerometers and 3 laser gyros.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What must be entered into the IRS before the aircraft can be moved?', '[{"id": "a", "text": "Flight plan.", "correct": false}, {"id": "b", "text": "Present position.", "correct": true}, {"id": "c", "text": "Cruise height.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The FMS Operational Database is', '[{"id": "a", "text": "updated once a month.", "correct": false}, {"id": "b", "text": "is fed with information on aircraft weight, cruise altitude and cost index before take off.", "correct": true}, {"id": "c", "text": "needs no update information.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Control surface feedback is fed back to', '[{"id": "a", "text": "the Flight Control Computer only.", "correct": true}, {"id": "b", "text": "the side stick controller only.", "correct": false}, {"id": "c", "text": "the Flight Control Computer and side stick controller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The accelerometer output in an INS/IRS is', '[{"id": "a", "text": "integrated once to give distance.", "correct": false}, {"id": "b", "text": "integrated twice to give velocity.", "correct": false}, {"id": "c", "text": "integrated twice to give distance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An INS/IRS Battery Unit provides', '[{"id": "a", "text": "standby power only whilst in flight.", "correct": false}, {"id": "b", "text": "standby power when airborne and on the ground.", "correct": true}, {"id": "c", "text": "standby power only on the ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If a fly by wire actuator loses hydraulic power the control surface will', '[{"id": "a", "text": "automatically move back to the neutral position.", "correct": false}, {"id": "b", "text": "remain rigid in the failure position.", "correct": false}, {"id": "c", "text": "remain in the failure position but may move due to aerodynamic pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'IRS alignment', '[{"id": "a", "text": "takes up to 10 minutes and the present position can be entered at any time during alignment.", "correct": true}, {"id": "b", "text": "takes up to 10 minutes and present position must be entered before alignment.", "correct": false}, {"id": "c", "text": "takes up to 10 minutes and the previous flight shut down present position is used for the alignment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A FMS has a total of how many Databases?', '[{"id": "a", "text": "1.", "correct": false}, {"id": "b", "text": "2.", "correct": true}, {"id": "c", "text": "4.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Fly by wire High Speed protection is', '[{"id": "a", "text": "to prevent tuck under.", "correct": true}, {"id": "b", "text": "to increase the pitch angle as speed increases.", "correct": false}, {"id": "c", "text": "to prevent high speed stall.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An IRS Laser gyro provides', '[{"id": "a", "text": "detection of the rate of movement about an aircraft axis.", "correct": true}, {"id": "b", "text": "detection of the earths gravitational force to establish true north.", "correct": false}, {"id": "c", "text": "detection of the earths rotation to establish true north.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The left and right cockpit displays', '[{"id": "a", "text": "are supplied from separate Symbol Generators at all times.", "correct": false}, {"id": "b", "text": "are supplied from the same Symbol Generator.", "correct": false}, {"id": "c", "text": "will only be supplied from the same symbol generator when all other symbol generators have failed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A single failure of a fly by wire control surface computer will', '[{"id": "a", "text": "cause the system to revert to an alternate law of operation.", "correct": false}, {"id": "b", "text": "not have any operational effect on the system.", "correct": true}, {"id": "c", "text": "cause the system to revert to a direct law of operation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What are the outputs from digital clocks used for?', '[{"id": "a", "text": "Flight data acquisition unit, Flight management computer and Voice recorder.", "correct": true}, {"id": "b", "text": "VOR, ILS and DME.", "correct": false}, {"id": "c", "text": "Weather radar, TCAS and ACARS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A full operation system BITE check will carry out a internal system test that ensures the system meets design requirements and is operational', '[{"id": "a", "text": "but will not move the controls.", "correct": false}, {"id": "b", "text": "as well as checking full system and will move the controls to their stops.", "correct": false}, {"id": "c", "text": "as well as checking full system but will not move the controls to their stops.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If on a flight deck EFIS system all the displays were missing one bit of information. This is most likely to be', '[{"id": "a", "text": "the input sensor bus and display controller.", "correct": false}, {"id": "b", "text": "the symbol generator and display.", "correct": false}, {"id": "c", "text": "the display controller and symbol generator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A centralised monitoring computer system is used', '[{"id": "a", "text": "to test system during flight and for BITE test of systems on the ground using a carry on control unit.", "correct": false}, {"id": "b", "text": "to test systems in flight and on the ground using a centralised on board control unit.", "correct": true}, {"id": "c", "text": "testing systems on the ground only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In an EFIS display, the lines, scales, indicator and synoptic are generated by', '[{"id": "a", "text": "raster scan.", "correct": false}, {"id": "b", "text": "synoptic scan.", "correct": false}, {"id": "c", "text": "stroke pulse.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The method of producing (white) lines for aircraft symbols, V/S scale etc. on an EADI is by', '[{"id": "a", "text": "raster scan.", "correct": false}, {"id": "b", "text": "trapezoidal input.", "correct": false}, {"id": "c", "text": "stroke pulse.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In modern aircraft, the output from the clock is used', '[{"id": "a", "text": "to synchronise the signals on the control bus.", "correct": false}, {"id": "b", "text": "to provide a clock pulse for CRT.", "correct": false}, {"id": "c", "text": "to give GMT details to the flight recorder and other systems.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'As a minimum requirement, when must a cockpit voice recorder start recording?', '[{"id": "a", "text": "From the start of the aircraft take off run.", "correct": false}, {"id": "b", "text": "After take off when airborne.", "correct": false}, {"id": "c", "text": "On first engine start.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The operational database of the FMS may have to be modified in flight', '[{"id": "a", "text": "It cannot be modified in flight", "correct": false}, {"id": "b", "text": "by the pilot. ← corrected answer", "correct": true}, {"id": "c", "text": "automatically by the DADC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'CADC outputs are', '[{"id": "a", "text": "altitude, vertical speed, IAS, mach no.", "correct": false}, {"id": "b", "text": "altitude, vertical speed, TAS, CAS, mach no, SAT, TAT.", "correct": true}, {"id": "c", "text": "altitude ,vertical speed, angle of attack, TAT, SAT.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If one EICAS CRT fails', '[{"id": "a", "text": "the FMS CDU will display the failed CRT data.", "correct": false}, {"id": "b", "text": "the remaining CRT will display primary EICAS data.", "correct": true}, {"id": "c", "text": "the standby CRT will automatically take over.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A method used in modern aircraft for reporting in flight faults to an engineering and monitoring ground station is', '[{"id": "a", "text": "TCAS II.", "correct": false}, {"id": "b", "text": "ACARS.", "correct": true}, {"id": "c", "text": "TAWS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The self test function on an EFIS system can be tested', '[{"id": "a", "text": "on the ground only.", "correct": false}, {"id": "b", "text": "in the air only.", "correct": false}, {"id": "c", "text": "in the air and on the ground.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Each of the symbol generator outputs in an EFIS system can be', '[{"id": "a", "text": "displayed on each individual display.", "correct": true}, {"id": "b", "text": "only no. 2 can be displayed on the no.1.", "correct": false}, {"id": "c", "text": "can not be interchanged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'BITE tests are inhibited for ground use during', '[{"id": "a", "text": "forward motion.", "correct": false}, {"id": "b", "text": "gear retraction.", "correct": false}, {"id": "c", "text": "take-off.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Modern aircraft with electronic displays would display information on airframe and engine on which system?', '[{"id": "a", "text": "Electronic centralised aircraft monitoring system (ECAM).", "correct": true}, {"id": "b", "text": "Flight management system.", "correct": false}, {"id": "c", "text": "EADI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The Flight data recorder starts recording', '[{"id": "a", "text": "after take off.", "correct": false}, {"id": "b", "text": "on aircraft roll out from stand.", "correct": false}, {"id": "c", "text": "after the first engine has started.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Data to flight data recorder can be taken from a communal data bus if', '[{"id": "a", "text": "the power is within flight data recorder limits.", "correct": false}, {"id": "b", "text": "it goes directly to it.", "correct": false}, {"id": "c", "text": "source isolation has been considered.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A central fault display system should be available through', '[{"id": "a", "text": "a bite test.", "correct": false}, {"id": "b", "text": "a central bite test box with clear LED indications.", "correct": false}, {"id": "c", "text": "a easily accessible multifunction control display unit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A flight data recorder should be capable of recording', '[{"id": "a", "text": "the last 25 hours.", "correct": false}, {"id": "b", "text": "the last 25 hours of aircraft flight.", "correct": false}, {"id": "c", "text": "the last 25 hours with engines running.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'BITE for ground use only is switched off', '[{"id": "a", "text": "on take-off.", "correct": true}, {"id": "b", "text": "when brakes are released.", "correct": false}, {"id": "c", "text": "when undercarriage up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Using I.N.S. an aircraft flies', '[{"id": "a", "text": "rhumb line.", "correct": false}, {"id": "b", "text": "course directed by ground station.", "correct": false}, {"id": "c", "text": "great circle route.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What warnings can an FMS provide?', '[{"id": "a", "text": "Ground faults only.", "correct": false}, {"id": "b", "text": "Discrete warnings.", "correct": true}, {"id": "c", "text": "Spurious faults.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Aircraft heading (HDG) is', '[{"id": "a", "text": "the angle between True North and the longitudinal axis of the aircraft.", "correct": true}, {"id": "b", "text": "the angle between True North and the actual track.", "correct": false}, {"id": "c", "text": "the angle between True North and the desired track.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Control Display Unit (CDU ) selection of TKE (Track Angle Error), displays', '[{"id": "a", "text": "difference in degrees that the aircraft is to the right or left of the desired track.", "correct": true}, {"id": "b", "text": "distance perpendicular from the selected track.", "correct": false}, {"id": "c", "text": "difference in degrees from True North in a clockwise direction from the desired track.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In the EICAS system, when is the maintenance mode available?', '[{"id": "a", "text": "Lower screen only - only available on the ground.", "correct": true}, {"id": "b", "text": "In flight.", "correct": false}, {"id": "c", "text": "On the upper and lower screens - only available on the ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On a modern aircraft when are BITE checks carried out?', '[{"id": "a", "text": "Continuously when system is in use.", "correct": true}, {"id": "b", "text": "After engine shut down.", "correct": false}, {"id": "c", "text": "Only when BITE selected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In an IN system, the purpose of the stable platform is to', '[{"id": "a", "text": "provide attitude reference.", "correct": false}, {"id": "b", "text": "prevent unwanted acceleration affecting the accelerometers.", "correct": true}, {"id": "c", "text": "stop the gyros from toppling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An IN system requires data from the', '[{"id": "a", "text": "Doppler system.", "correct": false}, {"id": "b", "text": "airdata computer.", "correct": true}, {"id": "c", "text": "satellites.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'TK (cross track) is the', '[{"id": "a", "text": "actual track across the earths surface.", "correct": false}, {"id": "b", "text": "angle in degrees that the aircraft track is left or right of desired track.", "correct": false}, {"id": "c", "text": "perpendicular distance from the desired track.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The output of an INS can be fed to the', '[{"id": "a", "text": "attitude indicators.", "correct": true}, {"id": "b", "text": "altimeters.", "correct": false}, {"id": "c", "text": "vertical speed indicators.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The three accelerometers on a strapdown system are mounted', '[{"id": "a", "text": "90Â° to each other.", "correct": true}, {"id": "b", "text": "parallel to each other.", "correct": false}, {"id": "c", "text": "120Â° apart.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Gyro-compassing is the term used for', '[{"id": "a", "text": "self-alignment in the vertical.", "correct": false}, {"id": "b", "text": "use of the gyro-magnetic compass system to align the platform.", "correct": false}, {"id": "c", "text": "self-alignment in azimuth.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Electronic Centralized Aircraft Monitoring System operates to', '[{"id": "a", "text": "give red warnings and amber cautions to display system status.", "correct": true}, {"id": "b", "text": "perform in-flight BITE only.", "correct": false}, {"id": "c", "text": "perform in-flight and ground tests of aircraft systems by carrying out a BITE.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The Centralized Aircraft Monitoring System uses the maintenance mode of operation', '[{"id": "a", "text": "on the ground only.", "correct": true}, {"id": "b", "text": "in the air only.", "correct": false}, {"id": "c", "text": "either ground or air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If part of a display is lost on a CRT, this could be due to', '[{"id": "a", "text": "an inoperative symbol generator or control panel.", "correct": false}, {"id": "b", "text": "an inoperative symbol generator or input sensor.", "correct": true}, {"id": "c", "text": "loss of power to the CRT.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A cyclic test (watch dog) should be performed for ECAM', '[{"id": "a", "text": "via MCDU.", "correct": false}, {"id": "b", "text": "during power up.", "correct": false}, {"id": "c", "text": "during flight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How does the symbol generator detect a program error?', '[{"id": "a", "text": "By looking at the even parity without error.", "correct": false}, {"id": "b", "text": "By looking at the odd parity without error.", "correct": true}, {"id": "c", "text": "By check sum bites for error detect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Relationship of CMCs to BITE systems is best described as', '[{"id": "a", "text": "CMCs replaced but is not related to the older BITE system.", "correct": false}, {"id": "b", "text": "CMCs monitors the individual BITE systems and presents data.", "correct": true}, {"id": "c", "text": "CMCs modifies and upgrades BITE systems.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An IRU interface test is carried out', '[{"id": "a", "text": "in the air.", "correct": false}, {"id": "b", "text": "only on the ground.", "correct": true}, {"id": "c", "text": "on the ground or in the air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'FMS system gives warning indications for', '[{"id": "a", "text": "take off and landings only.", "correct": false}, {"id": "b", "text": "any flight phase. ← corrected answer", "correct": true}, {"id": "c", "text": "cruise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'FMS CDU warnings are', '[{"id": "a", "text": "fail and MSG.", "correct": false}, {"id": "b", "text": "OFST and Fail.", "correct": false}, {"id": "c", "text": "MSG, fail and OFST.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'CMC (central maintenance computer) works to', '[{"id": "a", "text": "perform in-flight BITE and ground tests of aircraft systems, i.e. BITE.", "correct": true}, {"id": "b", "text": "give red warnings and amber cautions to display in accordance with system status.", "correct": false}, {"id": "c", "text": "perform in-flight BITE only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'BITE test carried out on input sensors and actuators performs', '[{"id": "a", "text": "validation of the information of the LRU.", "correct": false}, {"id": "b", "text": "a performance test of the system.", "correct": true}, {"id": "c", "text": "a test of the LRU.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A BITE check for automatic performance and fault monitoring is carried out when?', '[{"id": "a", "text": "Power-up self test.", "correct": false}, {"id": "b", "text": "For in-flight monitoring. ← corrected answer", "correct": true}, {"id": "c", "text": "To check the performance of the LRU.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In which of the following does TCAS II advise the pilot to make a manoeuvre?', '[{"id": "a", "text": "RA.", "correct": true}, {"id": "b", "text": "TA.", "correct": false}, {"id": "c", "text": "either RA or TA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What are the shapes of traffic shown on a TCAS display?', '[{"id": "a", "text": "White circles, red diamonds and amber squares.", "correct": false}, {"id": "b", "text": "White diamonds, red squares and amber circles.", "correct": true}, {"id": "c", "text": "White squares, red diamonds and amber circles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'If a display shows a red cross only, it is due to', '[{"id": "a", "text": "Symbol Generator failure.", "correct": true}, {"id": "b", "text": "CRT failure.", "correct": false}, {"id": "c", "text": "Altimeter failure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ACARS is an acronym for', '[{"id": "a", "text": "Aircraft Communicating Addressing and Reporting System.", "correct": true}, {"id": "b", "text": "Airborne Communicating Addressing and Reporting System.", "correct": false}, {"id": "c", "text": "ARINC Communicating Addressing and Reporting System.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When does the flight data recorder start recording ?', '[{"id": "a", "text": "Undercarriage up.", "correct": false}, {"id": "b", "text": "Parking brake released.", "correct": false}, {"id": "c", "text": "When the first engine starts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Brake temperature displayed on a flight deck CRT has', '[{"id": "a", "text": "a master warning light.", "correct": false}, {"id": "b", "text": "same colour throughout.", "correct": false}, {"id": "c", "text": "different colour for different temperatures.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When performing test on Electronic Displays using the Built In Test system', '[{"id": "a", "text": "CRT continues to display current data while the SGs and Display are internally tested.", "correct": false}, {"id": "b", "text": "SG injects a test signal into the display system and the word TEST appears on the screen.", "correct": true}, {"id": "c", "text": "displays cannot be tested it is only SG which are tested by BITE.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Heading reference required to establish initial heading during alignment sequence comes from', '[{"id": "a", "text": "FMS which gathers data from other Radio devices.", "correct": false}, {"id": "b", "text": "Magnetic compass installed on the airplane.", "correct": false}, {"id": "c", "text": "Earths Rotation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is primary mode of navigation on a modern aeroplane?', '[{"id": "a", "text": "Both GPS and IRS.", "correct": false}, {"id": "b", "text": "Only IRS.", "correct": true}, {"id": "c", "text": "Inch precise GPS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a flight director, how are small deviations corrected?', '[{"id": "a", "text": "Pilot input.", "correct": true}, {"id": "b", "text": "Instrument is calibrated at fitment to remove any possible error.", "correct": false}, {"id": "c", "text": "Instrument feedback.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'For a 3 dimensional fix in a Global Positioning System', '[{"id": "a", "text": "Minimum of 3 satellites must be in view.", "correct": false}, {"id": "b", "text": "Minimum of 2 satellites must be in view and altitude used to simulate a 3rd satellite.", "correct": false}, {"id": "c", "text": "Minimum of 4 satellites must be in view.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In an aircraft equipped with TCAS II and EFIS', '[{"id": "a", "text": "RA pitch command is shown on the EHSI and TA/RA traffic on the EADI.", "correct": false}, {"id": "b", "text": "RA pitch command is shown on the VSI and TA/RA traffic on the EHSI.", "correct": false}, {"id": "c", "text": "RA pitch command is shown on the EADI and TA/RA traffic on the EHSI.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The BITE indicator on a DFDR shows Yellow colour. This indicates', '[{"id": "a", "text": "power is ON but DFDR is not recording data.", "correct": false}, {"id": "b", "text": "power is ON and DFDR is recording data.", "correct": false}, {"id": "c", "text": "power is OFF or DFDR is at Fault.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a typical "Glass Cockpit" EICAS provides the following:', '[{"id": "a", "text": "engine parameters and system warnings only.", "correct": true}, {"id": "b", "text": "engine parameters and engine warnings only.", "correct": false}, {"id": "c", "text": "engine warnings only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'ECAM system was adopted for', '[{"id": "a", "text": "Airbus A310.", "correct": true}, {"id": "b", "text": "both Boeing and Airbus aircraft.", "correct": false}, {"id": "c", "text": "Boeing 757 and 767 aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A modern electromagnetic Flight Data Recorder, for recording data, could use:', '[{"id": "a", "text": "a floppy disk.", "correct": false}, {"id": "b", "text": "a plastic tape coated in ferrite.", "correct": true}, {"id": "c", "text": "a copper oxide string.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the minimum requirement for a CVR to start recording?', '[{"id": "a", "text": "When parking brake is released.", "correct": false}, {"id": "b", "text": "On commencement of flight.", "correct": false}, {"id": "c", "text": "When aircraft is capable of moving under its own power.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'As a minimum requirement when must a cockpit voice recorder start recording?', '[{"id": "a", "text": "Once airborne after take off.", "correct": false}, {"id": "b", "text": "Before engine start.", "correct": false}, {"id": "c", "text": "Once aircraft is ready to move under its own power.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A NOR gate with both inputs inverted becomes a', '[{"id": "a", "text": "NAND gate.", "correct": false}, {"id": "b", "text": "AND gate.", "correct": true}, {"id": "c", "text": "OR gate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Adding invertors to the two inputs of an AND gate makes a', '[{"id": "a", "text": "OR gate.", "correct": false}, {"id": "b", "text": "NOR gate.", "correct": true}, {"id": "c", "text": "NAND gate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which logic gate can be represented as a parallel circuit?', '[{"id": "a", "text": "OR gate.", "correct": true}, {"id": "b", "text": "Exclusive OR gate.", "correct": false}, {"id": "c", "text": "NAND gate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Making an inverter from a NAND or NOR gate is achieved by', '[{"id": "a", "text": "connecting the inputs.", "correct": true}, {"id": "b", "text": "inverting the input.", "correct": false}, {"id": "c", "text": "connecting two in series.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When will a NAND gate give logic 0 at the output?', '[{"id": "a", "text": "When both inputs are at 1.", "correct": true}, {"id": "b", "text": "When the inputs are different.", "correct": false}, {"id": "c", "text": "When both inputs are at 0.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The output of a NOT gate is logic 1. The input is', '[{"id": "a", "text": "logic 0.", "correct": true}, {"id": "b", "text": "logic 1.", "correct": false}, {"id": "c", "text": "both logic 1.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When the voltage that represents a logic 1 state is less than the voltage that represents a logic 0 state, the logic being used is', '[{"id": "a", "text": "either positive or negative.", "correct": false}, {"id": "b", "text": "positive.", "correct": false}, {"id": "c", "text": "negative.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The output of an AND gate having two inputs A and B is logic 1. The two inputs will have the logic states of', '[{"id": "a", "text": "A = 0, B = 0.", "correct": false}, {"id": "b", "text": "A = 1, B = 0.", "correct": false}, {"id": "c", "text": "A = 1, B = 1.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The output of an OR gate having two inputs A and B is logic 0. The two inputs will have the logic states', '[{"id": "a", "text": "A = 1, B = 0.", "correct": false}, {"id": "b", "text": "A = 0, B = 1.", "correct": false}, {"id": "c", "text": "A = 0, B = 0.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which logic gate has both inputs high to get an output?', '[{"id": "a", "text": "AND gate.", "correct": true}, {"id": "b", "text": "OR gate.", "correct": false}, {"id": "c", "text": "NAND gate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A NAND and NOR to become a NOT gate have', '[{"id": "a", "text": "inputs inverted.", "correct": false}, {"id": "b", "text": "outputs inverted.", "correct": false}, {"id": "c", "text": "inputs connected together.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An AND gate with inverted inputs and an inverted output is equivalent to', '[{"id": "a", "text": "an AND gate.", "correct": false}, {"id": "b", "text": "a NOR gate.", "correct": false}, {"id": "c", "text": "an OR gate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Logic gates internal operating mechanisms are produced from', '[{"id": "a", "text": "thin film resistors.", "correct": false}, {"id": "b", "text": "transistors.", "correct": true}, {"id": "c", "text": "diodes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A logic 1 may be represented in an analogue system by (where Q is an output of a latch / flipflop)', '[{"id": "a", "text": "switch closed / light off / Not Q.", "correct": false}, {"id": "b", "text": "positive / magnetised / Q.", "correct": true}, {"id": "c", "text": "switch open / light on / Q.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What sort of gate requires two negative input voltages to operate?', '[{"id": "a", "text": "NOT.", "correct": false}, {"id": "b", "text": "NAND.", "correct": true}, {"id": "c", "text": "OR.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In Positive Logic representation', '[{"id": "a", "text": "both states have same positive voltages but stage 1 has more current.", "correct": false}, {"id": "b", "text": "state 1 is more positive than state 0.", "correct": true}, {"id": "c", "text": "state 0 is more positive than state 1.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Switching within logic gates is normally achieved with the use of', '[{"id": "a", "text": "BTB.", "correct": false}, {"id": "b", "text": "relays.", "correct": false}, {"id": "c", "text": "diodes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The truth table of A=0011 B=0101 and C=0110 indicates that the logic device is', '[{"id": "a", "text": "a NOR gate.", "correct": false}, {"id": "b", "text": "an ECLUSIVE OR gate.", "correct": true}, {"id": "c", "text": "an AND gate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A NAND gate has inputs A and B and output C. If the output was zero, what are the inputs?', '[{"id": "a", "text": "A=1 B=1.", "correct": true}, {"id": "b", "text": "A=0 B=0.", "correct": false}, {"id": "c", "text": "A=1 B=0.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The "fan-in" in a gate is the', '[{"id": "a", "text": "number of inputs to a gate.", "correct": true}, {"id": "b", "text": "number of outputs from a gate.", "correct": false}, {"id": "c", "text": "number of inputs and outputs of a gate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Tristate devices are found', '[{"id": "a", "text": "on input circuits.", "correct": false}, {"id": "b", "text": "on output circuits.", "correct": true}, {"id": "c", "text": "on both input and output circuits.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A full adder has', '[{"id": "a", "text": "three inputs and two outputs.", "correct": true}, {"id": "b", "text": "two inputs and one output.", "correct": false}, {"id": "c", "text": "three inputs and one output.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a computer memory device, which one of these has the slowest access time?', '[{"id": "a", "text": "floppy disk.", "correct": false}, {"id": "b", "text": "magnetic tape.", "correct": true}, {"id": "c", "text": "8mm video tape.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The advantage of DRAM over SRAM is', '[{"id": "a", "text": "are cheaper to manufacture.", "correct": false}, {"id": "b", "text": "has a larger storage capacity per chip area.", "correct": true}, {"id": "c", "text": "they operate slower.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A BYTE is usually', '[{"id": "a", "text": "an 8 bit word.", "correct": true}, {"id": "b", "text": "a six bit word.", "correct": false}, {"id": "c", "text": "a 12 bit word.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the definition of baud rate?', '[{"id": "a", "text": "1 word per second.", "correct": false}, {"id": "b", "text": "1 byte per second.", "correct": false}, {"id": "c", "text": "1 bit per second.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Which would have the least components?', '[{"id": "a", "text": "ALU.", "correct": true}, {"id": "b", "text": "CPU.", "correct": false}, {"id": "c", "text": "LSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is a baud?', '[{"id": "a", "text": "A bit of data.", "correct": true}, {"id": "b", "text": "A block of data.", "correct": false}, {"id": "c", "text": "A byte of data.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a bi-stable memory circuit', '[{"id": "a", "text": "the memory is retained indefinably.", "correct": false}, {"id": "b", "text": "the memory is lost as soon as power is removed.", "correct": true}, {"id": "c", "text": "the memory needs to be refreshed constantly, even when power is on.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the advantage of series over parallel message sending?', '[{"id": "a", "text": "Only one pair of conductors.", "correct": true}, {"id": "b", "text": "More information sent.", "correct": false}, {"id": "c", "text": "Quicker.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A typical example of a mass storage memory device which is also WORM (Write Once Read Many) is', '[{"id": "a", "text": "an IC.", "correct": false}, {"id": "b", "text": "a magnetic tape.", "correct": false}, {"id": "c", "text": "a CD Rom.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A computer using RAM would utilize', '[{"id": "a", "text": "magnetic tape.", "correct": false}, {"id": "b", "text": "a compact disc.", "correct": false}, {"id": "c", "text": "an integrated circuit (chip).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Magnetic materials are used in', '[{"id": "a", "text": "ROMs only.", "correct": false}, {"id": "b", "text": "some RAMs.", "correct": true}, {"id": "c", "text": "EPROM.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A typical example of a mass storage device is', '[{"id": "a", "text": "IC.", "correct": false}, {"id": "b", "text": "magnetic tape.", "correct": false}, {"id": "c", "text": "CD.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is EPROM?', '[{"id": "a", "text": "Enhanced programmable read only memory.", "correct": false}, {"id": "b", "text": "Erasable programmable read only memory.", "correct": true}, {"id": "c", "text": "Erasable programming read only module.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How many bytes can be carried in a 32bit word?', '[{"id": "a", "text": "8 bytes.", "correct": false}, {"id": "b", "text": "4 bytes.", "correct": true}, {"id": "c", "text": "2 bytes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A common used material in computer manufacturing is', '[{"id": "a", "text": "ferrite material.", "correct": false}, {"id": "b", "text": "permeamag material.", "correct": false}, {"id": "c", "text": "ferromagnetic material.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Ferrite medium is used for computer memory because', '[{"id": "a", "text": "data is stored after the power is removed.", "correct": true}, {"id": "b", "text": "it is light.", "correct": false}, {"id": "c", "text": "it has low eddy current losses.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Data is usually stored in', '[{"id": "a", "text": "RAM.", "correct": true}, {"id": "b", "text": "ROM.", "correct": false}, {"id": "c", "text": "EEPROM.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Registers are used in digital computers to', '[{"id": "a", "text": "store bits of information in a permanent memory.", "correct": false}, {"id": "b", "text": "store a limited amount of information on a temporary basis.", "correct": true}, {"id": "c", "text": "keep a count of operations completed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A computer consist of at least the C.P.U and', '[{"id": "a", "text": "memory and input & output port.", "correct": true}, {"id": "b", "text": "memory, ALU, input & output port.", "correct": false}, {"id": "c", "text": "register section, ALU, timing and control section.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A basic computer would consist of', '[{"id": "a", "text": "register section, ALU and timing and control section.", "correct": false}, {"id": "b", "text": "memory, input/output ports and CPU.", "correct": true}, {"id": "c", "text": "RAM/ROM and input/output ports.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'DRAM', '[{"id": "a", "text": "requires a refreshing charge.", "correct": true}, {"id": "b", "text": "memory is stored when power supply is removed.", "correct": false}, {"id": "c", "text": "it does not require a refreshing charge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Bubble memory stores data on', '[{"id": "a", "text": "magnetic tape.", "correct": false}, {"id": "b", "text": "semiconductor material.", "correct": true}, {"id": "c", "text": "ferrite core.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An EPROM', '[{"id": "a", "text": "is non-volatile memory.", "correct": true}, {"id": "b", "text": "requires constant refreshing.", "correct": false}, {"id": "c", "text": "is erased after reading.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A computer requires to operate, a', '[{"id": "a", "text": "address bus, a data bus only.", "correct": false}, {"id": "b", "text": "data bus, a control bus, a address bus.", "correct": true}, {"id": "c", "text": "data bus, a control bus only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A computer is acting in real time when', '[{"id": "a", "text": "the CPU requires a clock pulse.", "correct": false}, {"id": "b", "text": "the output is equal to the input of data.", "correct": true}, {"id": "c", "text": "the time to access memory is equal to the data speed in.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the function of a status register in a microprocessor?', '[{"id": "a", "text": "To indicate the status of the processor.", "correct": true}, {"id": "b", "text": "In the ALU, to store the position of the program during an interrupt.", "correct": false}, {"id": "c", "text": "To synchronize the clock pulse.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'What is the purpose of the ALU?', '[{"id": "a", "text": "To store data being used by the CPU.", "correct": false}, {"id": "b", "text": "The part of the CPU unit where arithmetic & logic operations are carried out.", "correct": true}, {"id": "c", "text": "To convert serial into parallel data.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The CPU consists of', '[{"id": "a", "text": "ALU, timing and control section, register.", "correct": true}, {"id": "b", "text": "register and arithmetic logic unit only.", "correct": false}, {"id": "c", "text": "register, timing and control section only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'How is multiplication achieved in an ALU?', '[{"id": "a", "text": "by addition.", "correct": true}, {"id": "b", "text": "by subtraction.", "correct": false}, {"id": "c", "text": "by coupling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The smallest operation of a CPU is', '[{"id": "a", "text": "the processor cycle.", "correct": false}, {"id": "b", "text": "the processor sub-cycle.", "correct": false}, {"id": "c", "text": "the time cycle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Where does the clock signal in a microprocessor come from?', '[{"id": "a", "text": "ALU.", "correct": false}, {"id": "b", "text": "Memory.", "correct": false}, {"id": "c", "text": "Control unit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Where is the operating program for the CPU stored?', '[{"id": "a", "text": "Control unit.", "correct": false}, {"id": "b", "text": "ALU.", "correct": false}, {"id": "c", "text": "Memory unit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A priority encoder', '[{"id": "a", "text": "outputs the highest input.", "correct": true}, {"id": "b", "text": "outputs the selected input.", "correct": false}, {"id": "c", "text": "outputs the lowest input.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The smallest operation possible in a computer is the', '[{"id": "a", "text": "timing cycle.", "correct": true}, {"id": "b", "text": "processor sub-cycle.", "correct": false}, {"id": "c", "text": "processor cycle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A clock pulse in processor equipment', '[{"id": "a", "text": "is to synchronise everything.", "correct": true}, {"id": "b", "text": "is used for the maintenance tests.", "correct": false}, {"id": "c", "text": "is to give the correct timing when calculations are made.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'In a computer, the code that fetches correct data and feeds it to the ALU is called', '[{"id": "a", "text": "the instruction set.", "correct": true}, {"id": "b", "text": "ARINC.", "correct": false}, {"id": "c", "text": "the computer program.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'A computer processor has within it', '[{"id": "a", "text": "register, buffer, data bus.", "correct": false}, {"id": "b", "text": "ALU, register, memory.", "correct": false}, {"id": "c", "text": "ALU, control section, register.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The arithmetic logic unit (ALU) in a central processor unit (CPU) carries out', '[{"id": "a", "text": "addition, subtraction, multiplication and division.", "correct": true}, {"id": "b", "text": "computations as instructed.", "correct": false}, {"id": "c", "text": "timing and synchronisation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'The CPU requires a clock to determine', '[{"id": "a", "text": "the number of bits on the highway.", "correct": false}, {"id": "b", "text": "the speed of operation.", "correct": true}, {"id": "c", "text": "the date and time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'An ALU performs the following', '[{"id": "a", "text": "Arithmetic, Logic, Branch and Move Operations.", "correct": true}, {"id": "b", "text": "Input/Output operations, Arithmetic, Logic Functions.", "correct": false}, {"id": "c", "text": "Arithmetic, Logic, Branch and Find Operations.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'On an IC, pin 1 is to the left of the notch. Which way are the pins numbered?', '[{"id": "a", "text": "Left to right.", "correct": false}, {"id": "b", "text": "Anticlockwise.", "correct": true}, {"id": "c", "text": "Clockwise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'When 4 binary serial counters are connected in cascade for frequency division, what division factor is required?', '[{"id": "a", "text": "8.", "correct": false}, {"id": "b", "text": "16.", "correct": true}, {"id": "c", "text": "4.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), '3 binary counters in cascade. What is the division?', '[{"id": "a", "text": "32.", "correct": false}, {"id": "b", "text": "8.", "correct": true}, {"id": "c", "text": "16.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Within a 3 bit frequency cascade, division is to', '[{"id": "a", "text": "2.", "correct": false}, {"id": "b", "text": "4.", "correct": false}, {"id": "c", "text": "8.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M05.16'), 'Very Large Scale Integrated (VLSI) means the number of gates in a single IC is', '[{"id": "a", "text": "up to 10,000.", "correct": false}, {"id": "b", "text": "over 10,000.", "correct": true}, {"id": "c", "text": "up to 1000.", "correct": false}]'::jsonb, '{B1,B2}'),
